import type { Lesson } from './types.ts';
import { guideLesson } from './define.ts';

const s = (title:string,body:string,code?:string) => ({title,body,...(code ? {code} : {})});
const q = (question:string,options:string[],answer:number,explanation:string) => ({question,options,answer,explanation});
function a(slug:string,title:string,description:string,prerequisites:string[],objectives:string[],sections:Lesson['sections'],quiz:Lesson['quiz'],minutes=50):Lesson {
  return guideLesson('adv',slug,{title,description,prerequisites,objectives,sections,quiz,minutes,optional:true});
}

export const advancedLessons:Lesson[] = [
  a('springboards','Fronteras de dominancia y máximos de sufijo','Descarta estados que jamás podrán mejorar una respuesta y conserva solamente una frontera útil.',
    ['usaco-gold-intro-sorted-sets','usaco-plat-range-sweep'],['Reconocer dominancia entre estados','Mantener una frontera con un mapa ordenado'],[
      s('El estado que nunca conviene',`Imagina ofertas de transporte representadas por (alcance, ahorro). Una consulta pide el mayor ahorro entre ofertas cuyo alcance sea al menos x. Si tenemos (4,7) y (6,9), la primera sobra: cualquier consulta que permite usarla también permite la segunda, y esta ahorra más. Llamamos dominancia a esta comparación. La eliminación es segura porque solamente insertaremos ofertas; si después se permitiera borrar la oferta dominante, necesitaríamos recuperar información descartada.`),
      s('Una frontera ordenada',`Guardamos los pares no dominados en un mapa por alcance creciente. Sus ahorros deben disminuir estrictamente. Para consultar x, lower_bound(x) encuentra el primer alcance permitido; por el invariante, su ahorro es el máximo del sufijo. Antes de insertar (a,b), revisamos ese sucesor: si ya ofrece al menos b, rechazamos el nuevo par. En caso contrario, insertamos o mejoramos la clave a y borramos predecesores con ahorro menor o igual a b.`),
      s('Traza y programa',`Inserta (2,9), (5,6), (8,3). La consulta x=4 devuelve 6. Al insertar (6,8), desaparece (5,6), pero permanece (2,9): sirve para consultas pequeñas y todavía ahorra más. Ahora x=4 devuelve 8 y x=7 devuelve 3. El programa reproduce esta secuencia. Usamos optional para distinguir un sufijo vacío de un ahorro cero, pues los valores también podrían ser negativos. Cada borrado mantiene la frontera estrictamente decreciente.`, String.raw`#include <iostream>
#include <map>
#include <iterator>
#include <optional>
using namespace std;
map<int,long long> frontier;
void insert_offer(int x,long long y){
  auto it=frontier.lower_bound(x);
  if(it!=frontier.end() && it->second>=y) return;
  if(it!=frontier.end() && it->first==x) it=frontier.erase(it);
  it=frontier.emplace_hint(it,x,y);
  while(it!=frontier.begin()){
    auto before=prev(it);
    if(before->second>y) break;
    frontier.erase(before);
  }
}
optional<long long> query(int x){
  auto it=frontier.lower_bound(x);
  if(it==frontier.end()) return nullopt;
  return it->second;
}
int main(){
  insert_offer(2,9); insert_offer(5,6); insert_offer(8,3);
  cout<<*query(4)<<'\n';
  insert_offer(6,8);
  cout<<*query(4)<<' '<<*query(7)<<'\n';
}`),
      s('Costo y entrenamiento',`Una inserción puede borrar muchos pares, pero cada par insertado se borra como máximo una vez. Por tanto, N inserciones y Q consultas cuestan O((N+Q) log N) en total y O(N) memoria. No afirmamos que cada inserción individual sea rápida en el peor caso. Practica primero consultas con claves repetidas y ahorros negativos; después modela trampolines como eventos de un barrido. Decide explícitamente qué evento ocurre primero cuando coinciden un final y un inicio.`)
    ],q('Después de insertar (3,5), (7,2) y (8,6), ¿qué pares quedan?', ['Los tres','Solo (8,6)','(3,5) y (8,6)'],1,'(8,6) tiene alcance y ahorro al menos tan grandes como ambos pares anteriores, por lo que los domina.')),

  a('wavelet','Wavelet tree: valores dentro de intervalos','Responde cuántos valores pequeños hay en un intervalo y encuentra su k-ésimo elemento.',
    ['usaco-plat-segtree-ext','usaco-silver-prefix-sums'],['Mapear intervalos entre niveles','Resolver selección por rango de valores'],[
      s('Dividir los valores, conservar el orden',`Un wavelet tree divide el universo de valores en dos mitades. En cada nodo separa los elementos menores o iguales al punto medio de los mayores, respetando su orden relativo. Esta partición estable permite seguir un intervalo del arreglo original dentro de cada hijo. A diferencia de un segment tree habitual, la partición principal ocurre sobre valores, mientras las posiciones se trasladan mediante conteos de prefijo. Conviene comprimir coordenadas cuando los valores son grandes.`),
      s('La fórmula que mueve el intervalo',`Usa intervalos semiabiertos [l,r) y define pref[i] como la cantidad enviada al hijo izquierdo entre las primeras i posiciones del nodo. Entonces el intervalo izquierdo es [pref[l],pref[r]) y contiene pref[r]−pref[l] elementos. El derecho es [l−pref[l],r−pref[r]). Para buscar el k-ésimo menor, con k empezando en uno, baja a la izquierda si su cantidad alcanza k; en caso contrario, resta esa cantidad a k y baja a la derecha.`),
      s('Ejemplo trabajado',`En A=[4,1,3,2], la raíz divide valores [1,4] en [1,2] y [3,4]. Su prefijo izquierdo es [0,0,1,1,2]. Consulta el segundo menor de A[1,4)=[1,3,2]. El hijo izquierdo recibe [0,2), pues pref[1]=0 y pref[4]=2. Hay dos candidatos izquierdos, así que seguimos allí con k=2. Al dividir [1,2], solo uno es 1 y el segundo debe ser 2. Observa que nunca ordenamos el subarreglo consultado.`),
      s('Alcance, límites y práctica',`Con universo comprimido de tamaño σ, construir mediante particiones estables cuesta O(n log σ), cada selección o conteo cuesta O(log σ) y los prefijos ocupan O(n log σ) enteros en una implementación sencilla. Una representación con bitvectors y rank puede reducir memoria, pero exige otras técnicas. No confundas este esquema estático con actualizaciones arbitrarias: cambiar un elemento altera particiones. Practica todas las consultas de arreglos pequeños y compara con copiar y ordenar; incluye valores repetidos y verifica que 1≤k≤r−l.`)
    ],q('¿Cuántos elementos de [l,r) van al hijo izquierdo?', ['pref[r]−pref[l]','pref[r]−pref[l]+1','r−l−pref[r]'],0,'pref cuenta posiciones anteriores al extremo; la resta es exactamente el conteo del intervalo semiabierto.')),

  a('count-min','Contar mínimos y medir cobertura','Combina mínimo y multiplicidad para resolver consultas y áreas de uniones de rectángulos.',
    ['usaco-plat-rurq','usaco-plat-sweep-line'],['Construir un resumen asociativo con mínimo y conteo','Interpretar cobertura cero durante un barrido'],[
      s('Dos datos por nodo',`Saber solamente el mínimo no responde cuántas posiciones lo alcanzan. Guarda un par (mínimo,cantidad). Al combinar dos intervalos, gana el menor mínimo; si empatan, sumamos sus cantidades. El elemento neutro es (infinito,0), pues un intervalo vacío no aporta ocurrencias. Esta operación es asociativa porque describe exactamente la información del intervalo unido, por lo que funciona en un segment tree sin depender del orden particular de las combinaciones.`),
      s('Actualizaciones y un ejemplo',`Para A=[3,1,1,4], el resumen completo es (1,2). Si sumamos 2 al intervalo [1,3), queda [3,3,3,4] y el resumen cambia a (3,3). Una suma uniforme sobre un nodo modifica su mínimo pero conserva la cantidad de posiciones que lo alcanzan: esa es la razón por la cual admite propagación perezosa. Una asignación uniforme requiere otra etiqueta y establece la cantidad al tamaño del intervalo; no se debe tratar como una suma.`),
      s('De posiciones a longitudes',`En un barrido de rectángulos, cada hoja representa [y[i],y[i+1]) y guarda su longitud, no una unidad. El mínimo representa cobertura y la cantidad pasa a ser longitud que tiene esa cobertura mínima. Si el mínimo global es cero, longitud cubierta = longitud total − longitud del mínimo; si es positivo, todo está cubierto. Multiplica esta longitud por la distancia al siguiente evento x. Agrupa los eventos con igual x antes de avanzar para no introducir franjas ficticias.`, String.raw`#include <iostream>
#include <vector>
#include <limits>
using namespace std;
struct Node {long long minimum,count;};
Node merge(Node a,Node b){
  if(a.minimum<b.minimum) return a;
  if(b.minimum<a.minimum) return b;
  return {a.minimum,a.count+b.count};
}
int main(){
  vector<long long> a={3,1,1,4};
  Node answer={numeric_limits<long long>::max(),0};
  for(long long x:a) answer=merge(answer,{x,1});
  cout<<answer.minimum<<' '<<answer.count<<'\n';
}`),
      s('Complejidad y errores útiles',`Una consulta o suma por intervalo cuesta O(log n) con lazy propagation y la construcción ocupa O(n). La unión de R rectángulos cuesta O(R log R), incluyendo ordenar eventos y comprimir coordenadas. El programa solo demuestra la operación algebraica de combinación; el árbol perezoso se construye encima de ella. Practica con rectángulos anidados, bordes que se tocan y huecos grandes entre coordenadas. Si usas la cantidad de coordenadas en vez de sus diferencias, obtendrás áreas incorrectas aunque el conteo parezca coherente.`)
    ],q('Una hoja representa [2,8), sin cobertura. ¿Qué cantidad almacena?', ['1','6','8'],1,'En geometría se mide longitud: 8−2=6, no el número de índices comprimidos.')),

  a('segtree-beats','Segment tree beats','Acelera actualizaciones chmin con información sobre el máximo y un análisis amortizado.',
    ['usaco-plat-rurq'],['Decidir cuándo una actualización puede detenerse en un nodo','Distinguir costo amortizado de costo individual'],[
      s('Cuando lazy propagation no basta',`La operación chmin(l,r,x) sustituye cada valor a por min(a,x). Si un nodo solo guarda suma y máximo, no sabemos cuánto disminuir su suma: quizá un elemento supera x o quizá todos. Segment tree beats añade el máximo estricto segundo y la cantidad de apariciones del máximo. La idea consiste en aplicar rápidamente las actualizaciones que afectan únicamente a la clase de máximos, y descender cuando mezclan varias clases de valores.`),
      s('La condición decisiva',`Denota el máximo por M, el segundo máximo distinto por S y su multiplicidad por c. Si x≥M, no cambia nada. Si S<x<M, únicamente los c máximos bajan a x y actualizamos suma += (x−M)·c, luego M=x. Si x≤S, descendemos a los hijos. La desigualdad con S es estricta: en x=S se fusionarían clases y el resumen no contiene necesariamente la multiplicidad nueva que necesitamos.`),
      s('Una actualización a mano',`Considera [9,9,4,1], con suma 23, M=9, S=4 y c=2. Aplicar chmin a 6 disminuye la suma en (6−9)·2=−6: obtenemos suma 17 y máximos 6. Aplicar después chmin a 3 requiere bajar, porque el 4 también cambia. El resultado real es [3,3,3,1], suma 10. Al propagar, un padre puede imponer su máximo a los hijos; actualiza primero las etiquetas pendientes compatibles antes de reconstruir los resúmenes.`),
      s('Por qué paga su costo',`Para la variante de chmin y consultas de suma, sin sumar arbitrariamente rangos, el análisis potencial de clases de valores da O((n+q) log n) total con O(n) memoria. Una operación aislada puede visitar muchos nodos. Las variantes que combinan chmin, chmax y suma requieren invariantes adicionales y un análisis distinto; no heredan automáticamente esa cota. Practica contra un arreglo directo con valores iguales, negativos y umbrales exactamente iguales al segundo máximo. Elige un centinela suficientemente pequeño y evita multiplicar por él.`)
    ],q('En [8,8,5,2], ¿qué umbral permite actualizar solo la clase máxima?', ['x=5','x=6','x=4'],1,'El segundo máximo es 5; se requiere 5<x<8. Con x=6 cambian solo los dos ochos.')),

  a('persistent','Estructuras persistentes: consultar el pasado','Conserva versiones de un árbol compartiendo las partes que no cambiaron.',
    ['usaco-plat-segtree-ext','usaco-plat-sparse-segtree'],['Construir versiones mediante copia de caminos','Restar versiones de frecuencias para seleccionar por rango'],[
      s('Una raíz por versión',`Una estructura persistente conserva acceso a estados anteriores después de actualizar. En un segment tree, cambiar una posición afecta únicamente la hoja y sus ancestros. Creamos copias de esos nodos, apuntamos sus hijos no modificados hacia nodos antiguos y guardamos una raíz nueva. Nunca escribimos sobre un nodo compartido. La versión anterior sigue describiendo el mismo arreglo, aunque ambas raíces reutilicen casi toda la memoria. Esta técnica se conoce como copia del camino.`),
      s('Ejemplo de dos historias',`Parte de A=[2,0,5,1]. La raíz r0 suma 8. Al asignar A[1]=7, una raíz r1 suma 15 y conserva el subárbol derecho que representa [5,1]. Una consulta de [0,2) devuelve 2 en r0 y 9 en r1. También podemos actualizar r0 otra vez y crear una rama distinta; eso es persistencia completa. Si solo actualizamos la última versión, basta persistencia parcial, aunque el mecanismo de copia sea parecido.`),
      s('Frecuencias de prefijos',`Otra aplicación construye r[i] con las frecuencias de los primeros i elementos, sobre el universo de valores. Para consultar A[l,r), restamos conteos entre r[r] y r[l]. Si A=[3,1,3,2] y pedimos el segundo menor de [1,4), las diferencias representan {1,3,2}. En cada nivel calculamos el conteo izquierdo de ambas raíces; si alcanza k, descendemos a la izquierda, y en otro caso restamos ese conteo. La resta es válida porque los resúmenes son sumas de frecuencias.`),
      s('Memoria y comprobación',`Con árbol inicial completo, construcción O(n), cada actualización O(log n) y q cambios requieren O(n+q log n) nodos; cada consulta cuesta O(log n). En selección por valores la altura depende de σ, el universo comprimido. Guarda nodos por índice en un vector y no mantengas referencias que una realocación invalide. Practica creando tres versiones y verificando que ninguna consulta antigua cambia. La persistencia no convierte cualquier operación en invertible: no puedes restar máximos de raíces como si fueran conteos.`)
    ],q('¿Qué nodos se copian para una actualización puntual?', ['Todos los nodos','Solo la hoja','La hoja y el camino hasta la raíz'],2,'Solo esos O(log n) resúmenes cambian; los otros subárboles pueden compartirse sin mutarlos.')),

  a('treaps','Treaps y secuencias implícitas','Combina el orden de un árbol de búsqueda con prioridades aleatorias para partir y unir secuencias.',
    ['usaco-gold-intro-sorted-sets','usaco-plat-rurq'],['Mantener los invariantes de clave y prioridad','Implementar conceptualmente split, merge e inversión'],[
      s('Dos órdenes simultáneos',`Un treap es un árbol binario de búsqueda por clave y un montículo por prioridad aleatoria. Suponiendo prioridades independientes y distintas, su forma tiene la distribución de un árbol de búsqueda construido con una permutación aleatoria, por lo que su altura esperada es O(log n). Las prioridades no representan importancia del dato: únicamente equilibran la estructura. Se pueden desempatar con un identificador cuando el generador produce una colisión. El peor caso sigue siendo una cadena.`),
      s('Partir y unir',`split(T,k) separa los elementos menores que k del resto. Compara k con la raíz, separa recursivamente un hijo y reconstruye tamaños al volver. merge(A,B), bajo la precondición de que todas las claves de A preceden a las de B, elige la raíz con prioridad dominante y une recursivamente su hijo interior. Esta precondición es esencial: merge no ordena árboles arbitrarios. Insertar o borrar se expresa con unas pocas particiones y uniones.`),
      s('La posición como clave implícita',`En un treap implícito, la posición de un elemento depende del tamaño del hijo izquierdo; no guardamos claves que deban renumerarse. Para invertir [1,4) en [a,b,c,d,e], separamos A=[a], B=[b,c,d], C=[e]. Activamos una bandera de inversión en B, intercambiamos sus hijos y reconstruimos A+B+C: [a,d,c,b,e]. Antes de descender, propagamos la bandera a los hijos; después de cambiar enlaces, recalculamos tamaño y cualquier suma almacenada.`),
      s('Costo y taller',`Cada split o merge cuesta O(log n) esperado, las operaciones con un número constante de ellos también y la memoria es O(n). No confundas esperanza con garantía determinista. Para practicar, implementa primero insertar por posición y obtener una posición; luego añade inversión y suma de intervalos. Compara miles de secuencias cortas contra vector. Los fallos frecuentes son olvidar push antes de consultar tamaños, olvidar pull tras reconectar y mezclar extremos inclusivos con la convención [l,r). Evita reutilizar nodos borrados todavía referenciados.`)
    ],q('¿Qué condición necesita merge(A,B) en un treap de claves?', ['Todas las claves de A preceden a las de B','A y B tienen el mismo tamaño','Las prioridades de A son menores'],0,'La prioridad elige la raíz, pero el orden de búsqueda solo se preserva si las claves de A están antes que las de B.')),

  a('line-container','Contenedores dinámicos de rectas','Consulta mínimos de funciones lineales sin exigir que lleguen ordenadas por pendiente.',
    ['usaco-plat-convex-hull-trick','usaco-plat-sparse-segtree'],['Entender el invariante de Li Chao','Elegir entre envolvente ordenada y árbol sobre coordenadas'],[
      s('La consulta que queremos resolver',`Una transición como dp[i]=min(j<i){dp[j]+b[j]·a[i]} introduce una recta por cada j: pendiente b[j], intercepto dp[j]. Consultamos su mínimo en x=a[i]. Si las pendientes o las consultas no son monótonas, una deque sencilla puede fallar. Hay dos familias útiles: mantener explícitamente los puntos donde cambia la recta ganadora, o dividir el dominio de x mediante un árbol Li Chao. En ambas, las rectas pueden cruzarse como máximo una vez.`),
      s('Invariante del árbol Li Chao',`En cada nodo del dominio [L,R], conserva la mejor de sus rectas candidatas en el punto medio. Al insertar otra, intercámbialas si la nueva gana allí. La recta perdedora solo podría ganar en una de las dos mitades: compara en un extremo para decidir dónde continuar. Una consulta evalúa todas las rectas del camino hacia x y toma el mínimo. No afirmamos que la recta guardada gane en todo el intervalo; gana en el punto medio entre las candidatas comparadas.`),
      s('Dos rectas, varias respuestas',`Inserta f(x)=2x+1 y g(x)=−x+7 sobre enteros de 0 a 8. En x=4, g vale 3 y f vale 9, por lo que g puede quedarse en la raíz. En x=0, f vale 1 y g vale 7, así que f todavía necesita representarse hacia la izquierda. La igualdad ocurre en x=2. Consultar x=1 devuelve 3 y x=6 devuelve 1. Una implementación debe conservar correctamente empates y pendientes iguales.`),
      s('Cotas y experimentos',`Con dominio entero de tamaño C, Li Chao usa O(log C) por inserción y consulta. Si se conocen todas las coordenadas consultadas, se comprimen y se divide por sus índices, obteniendo O(log q); las comparaciones evalúan las coordenadas originales. Un contenedor de envolvente con divisiones enteras exactas puede lograr O(log n) amortizado, pero exige manejar redondeo negativo. Practica con rectas paralelas y extremos grandes. Evalúa pendiente·x+intercepto en un tipo suficientemente ancho para no convertir una comparación geométrica correcta en desbordamiento.`)
    ],q('¿Qué garantiza una recta almacenada en un nodo Li Chao?', ['Ganar en todos sus puntos','Ganar en su punto medio entre las candidatas comparadas','Tener menor pendiente'],1,'El punto medio decide cuál se conserva; la recta perdedora puede mejorar una mitad y por eso desciende.')),

  a('lagrange','Relajación lagrangiana: poner precio a una restricción','Elimina una dimensión de conteo mediante una penalización y estudia cuándo puedes recuperar la respuesta exacta.',
    ['usaco-gold-intro-dp','usaco-silver-binary-search','usaco-plat-convex-hull-trick'],['Optimizar valor y cantidad con una penalización','Justificar la condición de concavidad discreta'],[
      s('Cambiar una cantidad por un precio',`Supón que deseas maximizar beneficio usando exactamente K grupos, pero llevar K en el estado de programación dinámica resulta demasiado caro. Para una penalización λ, optimiza beneficio−λ·grupos y conserva también cuántos grupos usa la solución. Al aumentar el precio, la cantidad óptima puede elegirse de manera no creciente. Esto permite buscar λ. La monotonicidad del conteo por sí sola no garantiza que podamos obtener cualquier K: algunos conteos pueden saltarse.`),
      s('La condición que no se puede omitir',`Sea F(k) el mejor beneficio con k unidades. Si F es discretamente cóncava, las mejoras F(k)−F(k−1) no aumentan. Cada precio selecciona un punto de esta curva o un tramo de empate; el valor penalizado permite recuperar F(K) sumando λK en el precio de soporte adecuado. Sin concavidad solo se obtiene información de la envolvente cóncava, que puede estar por encima de un F(K) real. Hay que demostrar la propiedad del problema, no asumirla por semejanza.`),
      s('Un ejemplo con un salto legítimo',`Considera F(0)=0, F(1)=8, F(2)=13 y F(3)=18: las ganancias marginales son 8,5,5. Con λ=6 ganamos 0,2,1,0, así que elegimos un grupo. Con λ=5 los beneficios penalizados son 0,3,3,3. Si desempatas hacia la mayor cantidad, obtienes tres grupos, aunque buscabas K=2. La recuperación da 3+5·2=13, correcta porque ambos conteos pertenecen al mismo tramo lineal. Guarda el desempate consistentemente en todas las transiciones.`),
      s('Implementación y práctica',`Si una evaluación de λ tarda T(n) y los precios enteros relevantes están en un intervalo de amplitud W, la búsqueda cuesta O(T(n) log W). Para precios reales necesitas analizar precisión y recuperación, no trasladar una fórmula entera sin prueba. Practica primero una DP que compute todos los F(k) para n pequeño; dibuja sus diferencias y contrástala contra la versión penalizada. Un buen primer ejercicio es seleccionar subarreglos disjuntos. Documenta si buscas exactamente K o como máximo K, pues pueden requerir tratamientos diferentes.`)
    ],q('¿Por qué la monotonicidad del conteo no basta para recuperar F(K)?', ['Porque λ nunca puede ser entero','Porque K puede quedar debajo de la envolvente sin concavidad','Porque la búsqueda binaria necesita números positivos'],1,'Los precios solo seleccionan puntos soportados por rectas; un punto no cóncavo puede no ser óptimo para ningún precio.')),

  a('slope-trick','Slope trick: programar con funciones convexas','Representa cambios de pendiente y transforma una DP que vive sobre muchas posiciones.',
    ['usaco-silver-priority-queues','usaco-plat-convex-hull-trick'],['Representar funciones convexas lineales por tramos','Aplicar valor absoluto y mínimos de prefijo'],[
      s('Guardar las esquinas',`Una función convexa lineal por tramos tiene pendientes que solo aumentan. En vez de guardar un valor para cada x, podemos guardar los puntos donde su pendiente cambia y un término base. Por ejemplo, |x−a| baja con pendiente −1 antes de a y sube con pendiente +1 después. Sumar funciones de este tipo introduce esquinas. Slope trick organiza esas esquinas en montículos y permite efectuar ciertas transformaciones de programación dinámica sin recorrer todo el dominio.`),
      s('De una DP a una transformación',`Para aproximar una secuencia a[i] por una secuencia no decreciente b[i], con costo suma |a[i]−b[i]|, define F_i(x) como el costo mínimo si b[i]=x. Entonces F_i(x)=|x−a[i]|+min(y≤x)F_{i−1}(y). El mínimo de prefijo conserva la parte descendente de una función convexa y vuelve horizontal su parte ascendente después del mínimo. Por tanto, se pueden administrar cambios de pendiente mediante un montículo en vez de almacenar todos los posibles x.`),
      s('Una secuencia pequeña',`Para a=[3,1], F_1(x)=|x−3|. Su mínimo de prefijo vale 3−x cuando x<3 y cero cuando x≥3. Sumando |x−1|, el mínimo total es 2, alcanzado con valores finales entre 1 y 3; por ejemplo b=[1,1] o b=[2,2]. Una implementación específica para esta regresión isotónica inserta cada a dos veces en un max-heap y elimina una vez el máximo. Si el máximo supera a, añade esa diferencia al costo.`),
      s('El ámbito de la herramienta',`La variante anterior cuesta O(n log n) y O(n) memoria. Una biblioteca general suele usar dos montículos, desplazamientos perezosos y el valor mínimo para admitir suma de bisagras y traslaciones. Cada operación debe preservar convexidad y tener una interpretación concreta; slope trick no optimiza una DP arbitraria. Practica calculando a mano las pendientes para [5,2,4] y comparando el costo con enumeración de b en un dominio pequeño. Si necesitas reconstruir la secuencia, el costo mínimo por sí solo no contiene todos los predecesores necesarios.`)
    ],q('¿Qué hace min(y≤x)F(y) a una función convexa?', ['La vuelve constante en todo el dominio','Mantiene la bajada y aplana la parte posterior al mínimo','Invierte todas sus pendientes'],1,'Antes del mínimo conviene y=x; después, ya puede elegirse un minimizador anterior y el resultado permanece en el mínimo.')),

  a('sp-neg','Caminos mínimos con aristas negativas','Aprende Bellman–Ford, ciclos negativos y potenciales para recuperar pesos no negativos.',
    ['usaco-gold-shortest-paths'],['Detectar ciclos negativos alcanzables','Comprender reponderación mediante potenciales'],[
      s('Por qué Dijkstra deja de bastar',`Dijkstra cierra un vértice cuando cree que ninguna ruta futura puede abaratarlo. Una arista negativa rompe ese argumento: desde s hay una arista a a de peso 2 y otra a b de peso 5, pero b→a pesa −10. Cerrar a con distancia 2 sería prematuro porque existe una ruta de costo −5. Los pesos negativos no implican automáticamente que el problema carezca de solución; el problema aparece cuando un ciclo negativo puede repetirse en una ruta relevante.`),
      s('Bellman–Ford y su invariante',`Inicializa dist[s]=0 y el resto infinito. En cada ronda relaja todas las aristas u→v: si u es alcanzable, intenta dist[v]=min(dist[v],dist[u]+w). Después de n−1 rondas se han considerado todas las rutas simples necesarias. Si todavía se puede mejorar en otra ronda, existe un ciclo negativo alcanzable desde s. Para decidir si la distancia a t es menos infinito, además debe existir un camino desde ese ciclo hasta t; propaga desde los vértices mejorados.`),
      s('Potenciales que preservan rutas',`Si no hay ciclos negativos, añade una superfuente con aristas cero y calcula potenciales h mediante Bellman–Ford. Define w'(u,v)=w(u,v)+h[u]−h[v]. La desigualdad h[v]≤h[u]+w garantiza w'≥0. En una ruta, los potenciales interiores se cancelan y su costo nuevo es el antiguo+h[s]−h[t], así que el orden entre rutas de iguales extremos no cambia. Ya puedes aplicar Dijkstra y recuperar dist(s,t)=dist'(s,t)−h[s]+h[t].`),
      s('Cotas y prueba diferencial',`Bellman–Ford tarda O(nm) y usa O(n+m) contando el grafo; puede terminar antes si una ronda no cambia nada. Johnson añade Dijkstra desde cada origen y cuesta O(nm+n(m+n) log n) con heap binario. No uses SPFA como si garantizara rapidez: su peor caso también puede ser O(nm). Practica grafos desconectados, ciclos negativos que no llegan al destino y aristas paralelas. Nunca sumes un peso a infinito; limita magnitudes y usa un tipo ancho para distancias negativas repetidas.`)
    ],q('Un ciclo negativo es alcanzable desde s, pero no puede llegar a t. ¿Implica dist(s,t)=−∞?', ['Sí, siempre','No; debe poder influir en una ruta hasta t','Solo si tiene tres vértices'],1,'Para reducir indefinidamente una ruta s→t hay que llegar al ciclo, repetirlo y salir hacia t.')),

  a('eulerian-tours','Recorridos eulerianos y algoritmo de Hierholzer','Recorre cada arista exactamente una vez y distingue esta tarea de visitar cada vértice.',
    ['usaco-silver-graph-traversal'],['Reconocer las condiciones de existencia','Construir recorridos con identificadores de arista'],[
      s('La unidad que se consume es una arista',`Un recorrido euleriano utiliza cada arista exactamente una vez; puede visitar un vértice muchas veces. En un grafo no dirigido con alguna arista, los vértices de grado positivo deben pertenecer a una componente. Hay circuito si todos los grados son pares, y camino abierto si exactamente dos son impares. En un grafo dirigido, un camino abierto necesita un inicio con salida−entrada=1, un final con entrada−salida=1 y balance cero en los demás, además de conectividad débil del soporte.`),
      s('Caminar y deshacer',`Hierholzer mantiene una pila. Mientras el vértice superior tenga una arista sin usar, la consume y empuja su vecino. Cuando ya no tiene salidas, lo retira y añade a la respuesta. La respuesta sale invertida: el retroceso va colocando los circuitos que se descubren dentro del recorrido. En grafos no dirigidos cada arista aparece dos veces en las listas, por eso se necesita un identificador compartido y una marca used; no basta marcar vértices.`),
      s('Ejemplo que vuelve al inicio',`En el triángulo 0–1–2–0, los tres grados son dos. Podemos caminar 0,1,2,0 y luego vaciar la pila; al invertir lo acumulado recuperamos el circuito. El programa construye este grafo y consume aristas con identificadores. Para un problema general, valida antes las condiciones y el inicio. Al terminar, comprueba que la respuesta contiene m+1 vértices: un recorrido de tamaño menor delata aristas de otra componente o una elección de inicio incompatible.`, String.raw`#include <iostream>
#include <vector>
#include <algorithm>
#include <utility>
using namespace std;
int main(){
  vector<vector<pair<int,int>>> g(3);
  auto add=[&](int u,int v,int id){g[u].push_back({v,id});g[v].push_back({u,id});};
  add(0,1,0); add(1,2,1); add(2,0,2);
  vector<int> pos(3), stack={0}, answer;
  vector<bool> used(3);
  while(!stack.empty()){
    int u=stack.back();
    while(pos[u]<(int)g[u].size() && used[g[u][pos[u]].second]) ++pos[u];
    if(pos[u]==(int)g[u].size()){answer.push_back(u);stack.pop_back();}
    else {auto [v,id]=g[u][pos[u]++];used[id]=true;stack.push_back(v);}
  }
  reverse(answer.begin(),answer.end());
  for(int v:answer) cout<<v<<' ';
  cout<<'\n';
}`),
      s('Tiempo y ejercicios',`Cada entrada de la lista se inspecciona como máximo una vez usando un puntero por vértice, así que el costo es O(n+m) y la memoria O(n+m). Buscar desde el principio una arista disponible en cada paso puede arruinar esta cota. Practica con dos aristas paralelas entre los mismos vértices, un lazo y una cadena. Después modela un rompecabezas de palabras mediante prefijos y sufijos: cada palabra es una arista. Distingue siempre las condiciones de grafos dirigidos de las de grafos no dirigidos.`)
    ],q('¿Cuántos vértices tiene la lista de un recorrido que consume m aristas?', ['m−1','m','m+1'],2,'Cada arista agrega una transición; la lista incluye además el vértice inicial.')),

  a('BCC-2CC','Puentes, articulaciones y componentes biconexas','Identifica puntos únicos de falla y comprime regiones que conservan conectividad.',
    ['usaco-silver-graph-traversal','usaco-gold-dsu'],['Interpretar low-link en un DFS no dirigido','Distinguir falla de arista y falla de vértice'],[
      s('Dos preguntas parecidas, distintas',`Una arista es puente si quitarla aumenta las componentes conexas. Un vértice es articulación si eliminarlo y sus aristas aumenta ese número. En dos triángulos que comparten solo un vértice, no hay puentes, pero el vértice compartido sí es articulación. Por eso las componentes conexas tras retirar puentes y los bloques biconexos por vértices no son lo mismo. Esta distinción determina si construyes un árbol de puentes o un árbol bloque-articulación.`),
      s('Tiempos de entrada y low',`Durante DFS asigna tin[u] y calcula low[u], el menor tiempo de entrada alcanzable desde el subárbol de u usando aristas de árbol y a lo sumo una arista de regreso. Para un hijo v, la arista u–v es puente si low[v]>tin[u]: no existe retorno al ancestro u ni más arriba. Si u no es raíz, es articulación cuando algún hijo cumple low[v]≥tin[u]. La igualdad importa: poder regresar a u no salva la conectividad cuando u desaparece.`),
      s('Ejemplo y extracción de bloques',`En las aristas 0–1,1–2,2–0,1–3, el triángulo admite regreso a 0. La arista 1–3 es puente y 1 es articulación. Para sacar componentes de aristas no separadas por puentes, identifica puentes y recorre ignorándolos. Para bloques biconexos por vértices, guarda aristas en una pila DFS; cuando low[v]≥tin[u], retira hasta u–v y forma un bloque. La raíz DFS requiere una regla especial: es articulación si tiene al menos dos hijos DFS.`),
      s('Robustez y práctica',`Ambas búsquedas cuestan O(n+m) y O(n+m) memoria. En un multigrafo, ignora únicamente la arista padre por su identificador, no todos los vecinos iguales al padre: una arista paralela puede impedir que exista un puente. Procesa todas las componentes del grafo y vigila la profundidad de recursión. Practica generando grafos de seis vértices y quitando una arista o un vértice para obtener una respuesta lenta verificable. Después consulta cuántos puentes separan dos ciudades mediante LCA sobre el árbol comprimido.`)
    ],q('Para un hijo DFS v de u, ¿cuándo es puente u–v?', ['low[v]≥tin[u]','low[v]>tin[u]','low[v]<tin[u]'],1,'Si low[v]=tin[u], hay una ruta de regreso a u y la arista no es un puente; se necesita desigualdad estricta.')),

  a('SCC','Componentes fuertemente conexas y 2-SAT','Agrupa vértices mutuamente alcanzables y razona sobre dependencias sin ciclos.',
    ['usaco-gold-toposort','usaco-silver-graph-traversal'],['Construir la condensación de un grafo dirigido','Reducir restricciones booleanas a implicaciones'],[
      s('Mutua alcanzabilidad',`En un grafo dirigido, dos vértices pertenecen a la misma componente fuertemente conexa si cada uno puede llegar al otro. Esta relación divide los vértices en grupos disjuntos. Al comprimir cada grupo y mantener aristas entre grupos obtenemos un DAG: un ciclo entre componentes demostraría que todas podían alcanzarse mutuamente y en realidad eran una sola. La condensación permite aplicar programación dinámica o un orden topológico a problemas cuyo grafo original contenía ciclos.`),
      s('Kosaraju paso a paso',`Haz DFS en el grafo original y añade cada vértice a una lista cuando termina su exploración. Luego recorre los vértices en orden inverso de finalización, haciendo DFS sobre el grafo con aristas invertidas. Cada nueva búsqueda encuentra una componente completa. El primer orden dirige la segunda pasada hacia componentes que no pueden escaparse hacia componentes todavía sin asignar. Tarjan ofrece otra opción de una pasada con low-link y una pila de vértices activos; no mezcles sus reglas con las de puentes no dirigidos.`),
      s('Un ejemplo y restricciones booleanas',`Con 0→1,1→0,1→2,2→3,3→2, hay componentes {0,1} y {2,3}, conectadas en ese orden. Para 2-SAT, la cláusula (a o b) equivale a las implicaciones no a→b y no b→a. Construye dos vértices por variable. El sistema es imposible exactamente cuando una variable y su negación están en la misma componente. Una asignación se obtiene según el orden de componentes; la comparación concreta de identificadores depende de cómo los numeró tu algoritmo.`),
      s('Costo y comprobaciones',`Kosaraju usa O(n+m) tiempo y memoria, incluyendo el grafo inverso. Para 2-SAT con v variables y c cláusulas, el tamaño es O(v+c). No deduzcas una asignación copiando una desigualdad de otro código: verifica la orientación de tu orden y comprueba todas las cláusulas al final. Practica fórmulas de tres variables enumerando sus ocho asignaciones. Añade cláusulas unitarias como (x o x), contradicciones explícitas y vértices aislados. En grafos muy profundos una pila iterativa evita desbordar la pila de llamadas.`)
    ],q('¿Qué contradicción detecta 2-SAT mediante componentes?', ['Dos variables distintas en una SCC','x y no x en la misma SCC','Una SCC con un solo vértice'],1,'Las implicaciones obligarían simultáneamente a alcanzar una afirmación y su negación; ninguna elección de x puede satisfacerlas.')),

  a('offline-del','Borrados offline y DSU con rollback','Convierte aristas que aparecen y desaparecen en intervalos sobre el tiempo.',
    ['usaco-gold-dsu','usaco-plat-segtree-ext'],['Registrar cambios reversibles en DSU','Recorrer un árbol de intervalos de actividad'],[
      s('Por qué borrar es difícil',`Un DSU normal une componentes pero no recuerda cómo separarlas cuando una arista desaparece. Si conocemos todas las operaciones por adelantado, podemos cambiar la pregunta: cada arista está activa durante ciertos intervalos de tiempo. Un segment tree sobre esos tiempos almacena la arista en los O(log q) nodos cuya unión cubre su intervalo de actividad. Al entrar a un nodo solo agregamos aristas, y al salir deshacemos exactamente los cambios realizados allí.`),
      s('Rollback sin compresión de caminos',`Usa unión por tamaño, pero evita compresión de caminos en find: sus escrituras serían numerosas y complicarían la reversión. Cada unión exitosa apila la raíz absorbida, el tamaño anterior del ganador y cualquier agregado modificado. Una instantánea es simplemente el tamaño de la pila. Para volver a ella, retira cambios hasta alcanzar ese tamaño. Sin compresión, unión por tamaño limita la altura a O(log n), por lo que find conserva una cota determinista adecuada.`),
      s('Un recorrido temporal',`Considera t0: agregar 0–1; t1: consultar 0 con 2; t2: agregar 1–2; t3: consultar; t4: borrar 0–1; t5: consultar. Las respuestas son no, sí y no. La primera arista vive en [0,4) y la segunda en [2,6). Durante el DFS temporal, antes de responder una hoja se han unido exactamente las aristas cuyos intervalos contienen ese tiempo. Al volver de un hijo, restaura la instantánea para que sus aristas no contaminen al hermano.`),
      s('Complejidad y casos difíciles',`Con K intervalos de actividad y Q consultas, el costo es O((K log q+Q) log n), más el preprocesamiento, y la memoria O(n+K log q). Una arista agregada varias veces exige contar multiplicidades o usar identificadores; borrar una copia no necesariamente la desactiva. Define si la consulta ve el estado antes o después de la operación del mismo índice. Practica primero solo borrados procesando el tiempo al revés; después implementa la versión general y compárala con BFS en cada consulta de casos pequeños.`)
    ],q('¿Por qué suele omitirse la compresión de caminos en DSU con rollback?', ['Porque rompe conectividad','Porque introduce muchas escrituras que también habría que deshacer','Porque unión por tamaño deja de funcionar'],1,'Rollback necesita restaurar cada cambio; unión por tamaño sin compresión mantiene find en O(log n) con un registro sencillo.')),

  a('eulers-formula','Fórmula de Euler y grafos planares','Relaciona vértices, aristas y regiones y comprueba cuándo un dibujo permite aplicar la fórmula.',
    ['usaco-bronze-intro-graphs','usaco-plat-geo-pri'],['Contar la cara exterior y las componentes','Obtener límites de aristas en grafos simples planares'],[
      s('La cara exterior también cuenta',`Un grafo planar admite un dibujo en el plano donde las aristas solo se cruzan en sus extremos. Para un dibujo con V vértices, E aristas, F caras incluida la región exterior y C componentes conexas, se cumple V−E+F=1+C. En el caso conexo queda V−E+F=2. Si dos segmentos se cruzan interiormente y decides interpretar ese cruce como conexión, debes convertirlo en un vértice y partir las aristas antes de contar.`),
      s('Una prueba mediante aristas',`Un bosque con C componentes tiene E=V−C y una sola cara; satisface la igualdad. Al añadir una arista que une componentes, E aumenta uno y C disminuye uno, sin crear cara. Al añadir una arista cuyos extremos ya están conectados, el ciclo separa una cara en dos: E y F aumentan uno. Estas operaciones explican la fórmula y aclaran por qué una arista puente no crea una región nueva, aunque tenga dos lados en el dibujo.`),
      s('Contar y deducir imposibilidad',`Un cuadrado con una diagonal tiene V=4, E=5 y F=3: las dos regiones triangulares y el exterior. Dos cuadrados separados tienen V=8, E=8, C=2 y F=3, no cuatro: comparten una misma cara exterior. En un grafo simple planar con V≥3, cada cara tiene al menos tres incidencias de aristas y cada arista aporta dos, de donde 3F≤2E y E≤3V−6 para el caso conexo. Esto demuestra que K5 no es planar, pues 10>9.`),
      s('Límites y ejercicios',`Evaluar la fórmula con conteos conocidos cuesta O(1); construir las intersecciones de un dibujo puede ser el verdadero problema y requerir un barrido. La desigualdad E≤3V−6 es necesaria, pero no suficiente para planaridad. Lazos, aristas múltiples y grafos con menos de tres vértices requieren revisar sus hipótesis. Practica dibujando una arista puente que une dos ciclos y cuenta incidencias sin olvidar sus dos lados. Después usa un DSU para rastrear cuándo una nueva conexión cierra un ciclo y aumenta el número de regiones.`)
    ],q('Dos triángulos separados tienen V=6, E=6 y C=2. ¿Cuántas caras hay?', ['2','3','4'],1,'F=1+C−V+E=3: dos interiores y una única región exterior.')),

  a('critical','Dominadores: ciudades que toda ruta debe atravesar','Reconoce vértices inevitables desde un origen y aprende la estructura del árbol de dominadores.',
    ['usaco-silver-graph-traversal','usaco-gold-toposort'],['Definir dominación con todas las rutas dirigidas','Distinguir dominadores, articulaciones y semidominadores'],[
      s('Una obligación en rutas dirigidas',`Fijamos un origen s. Un vértice d domina a v si todo camino de s a v pasa por d; consideramos solo vértices alcanzables desde s. El propio v y s siempre dominan a v. En el diamante s→a→t y s→b→t, ni a ni b dominan t. Si añadimos t→u como única entrada a u, t sí domina u. Esta noción depende del origen y de la dirección de las aristas, a diferencia de las articulaciones no dirigidas.`),
      s('Una recurrencia para entenderlo',`Los conjuntos cumplen Dom(s)={s} y Dom(v)={v} unión la intersección de Dom(p) para todos los predecesores alcanzables p de v. En un DAG puedes calcularlos en orden topológico. Con ciclos, inicializa cada conjunto no inicial con todos los alcanzables e itera hasta un punto fijo: los conjuntos disminuyen. Una sola pasada DFS no basta. Con bitsets de palabras de w bits, cada ronda cuesta O((n+m)·ceil(n/w)); la cantidad de rondas debe incluirse en el análisis.`),
      s('Del conjunto al árbol',`Los dominadores estrictos de un vértice se ordenan en una cadena. El más cercano a v se llama dominador inmediato idom(v), y esos enlaces forman un árbol con raíz s. Para obtener los vértices críticos hacia t, sube desde t hasta s en ese árbol. El algoritmo de Lengauer–Tarjan usa numeración DFS, semidominadores y consultas link/eval para evitar conjuntos completos. Un semidominador es un auxiliar definido mediante caminos con restricciones de numeración; no debes confundirlo con idom ni usarlo directamente como respuesta.`),
      s('Elegir una implementación verificable',`Una comprobación lenta elimina cada candidato y hace una búsqueda desde s: cuesta O(n(n+m)) y sirve como oráculo en grafos pequeños. Lengauer–Tarjan tiene variantes O((n+m) log n) y otras con unión balanceada de costo casi lineal; la cota depende de la implementación de link/eval. Estudia la versión exacta antes de atribuirle la mejor complejidad. Practica diamantes, ciclos y vértices inalcanzables, comparando el árbol contra eliminación directa. El resultado también aparece en análisis de control de flujo de compiladores.`)
    ],q('En s→a→t y s→b→t, ¿quiénes dominan t?', ['s, a y t','s y t','Todos los vértices'],1,'Hay una ruta que evita a y otra que evita b; ambas deben pasar por s y terminar en t.')),

  a('link-cut-tree','Link-cut trees: bosques que cambian','Mantén caminos de un bosque mientras enlazas y cortas aristas.',
    ['usaco-adv-treaps','usaco-plat-hld'],['Separar el bosque representado de los árboles auxiliares','Entender access, makeroot, link y cut'],[
      s('Cuando la descomposición deja de ser fija',`Heavy-light decomposition funciona muy bien para un árbol que no cambia de estructura. Si llegan operaciones de conectar dos árboles o cortar una arista, sus caminos pesados pueden dejar de ser válidos. Un link-cut tree representa un bosque mediante caminos preferidos, cada uno guardado en un árbol auxiliar splay. El bosque original y los splay son estructuras distintas: un padre en el splay no significa necesariamente ser padre directo en el árbol del problema.`),
      s('Exponer un camino',`access(v) reorganiza caminos preferidos para exponer el camino desde la raíz representada hasta v; luego splay(v) lo coloca en una posición cómoda para consultar su agregado. makeroot(v) realiza access y revierte ese camino mediante una etiqueta perezosa, cambiando la raíz representada. Para consultar el camino u–v, aplica makeroot(u), access(v) y lee el agregado del splay de v. Sumas y máximos son ejemplos sencillos; información dependiente de orientación necesita resúmenes de ambos sentidos.`),
      s('Enlazar y cortar con condiciones',`En el bosque 1–2–3 y 4–5, link(3,4) crea el camino 1–2–3–4–5. Antes debes verificar que 3 y 4 están en árboles distintos; de otra forma introduces un ciclo y sales del modelo de bosque. cut(2,3) debe separar una arista real, no simplemente desconectar los extremos de una ruta larga. Tras makeroot(2) y access(3), comprueba la adyacencia expuesta antes de modificar enlaces. Una consulta posterior entre 1 y 5 ya no tiene camino.`),
      s('Amortización y laboratorio',`Las operaciones estándar cuestan O(log n) amortizado mediante el análisis de splay y caminos preferidos, con O(n) memoria. Una operación individual puede costar más. Antes de cada rotación, propaga inversiones desde los ancestros auxiliares; después, recalcula agregados. Las consultas de subárbol necesitan contribuciones virtuales adicionales y no salen gratis de un agregado de caminos. Practica en un bosque de diez vértices comparando todas las operaciones con BFS y reconstrucción explícita del camino. Registra la diferencia entre raíz auxiliar y raíz representada en cada función.`)
    ],q('¿Cuándo es válida link(u,v) en un bosque dinámico?', ['Siempre que u≠v','Cuando u y v están en componentes distintas','Solo cuando ambos son hojas'],1,'Si ya están conectados, añadir la arista cerraría un ciclo; un link-cut tree estándar representa bosques.')),

  a('comb-sub','DP de árboles: combinar subárboles','Mezcla presupuestos o cantidades entre hijos sin atribuir un costo cúbico innecesario.',
    ['usaco-gold-dp-trees','usaco-gold-knapsack'],['Derivar una convolución min-plus entre hijos','Acotar el trabajo usando tamaños reales de subárboles'],[
      s('Una mochila en cada vértice',`Define dp[u][k] como el menor costo de seleccionar k objetos del subárbol de u. Cada hijo aporta un conjunto independiente de posibilidades, así que sus tablas se combinan como mochilas. Si existen reglas entre padre e hijo, por ejemplo descuentos condicionados a seleccionar al padre, añade un pequeño estado booleano y especifica qué estados del hijo son compatibles. Ese estado tiene significado local; no debe esconder decisiones que cambien las reglas de todos los ancestros.`),
      s('La transición correcta',`Sean A las posibilidades de los hijos ya procesados y B las de un nuevo hijo. La tabla resultante cumple C[k]=min(i+j=k)(A[i]+B[j]). Inicializa C con infinito y usa una tabla nueva para no reutilizar el mismo hijo varias veces dentro de una mezcla. Itera i solo hasta la cantidad real de objetos procesados y j hasta el tamaño del hijo. Tras combinar, el rango válido crece en el tamaño incorporado, no directamente hasta n en todas las operaciones.`),
      s('Dos hijos a mano',`Supón que A=[0,4,9] y B=[0,3], donde cada índice indica cuántos objetos compras. Entonces C[0]=0, C[1]=min(4+0,0+3)=3, C[2]=min(9+0,4+3)=7 y C[3]=9+3=12. Si solo tienes presupuesto 8, puedes adquirir dos objetos. Este ejemplo muestra por qué elegir primero lo más barato de cada hijo no basta: las tablas pueden incluir dependencias internas y deben combinarse por cantidad exacta.`),
      s('La cuenta amortizada de parejas',`Una mezcla de bloques de tamaños a y b examina O(ab) parejas, además de términos lineales. Cada pareja de objetos de bloques distintos se encuentra una sola vez, cuando sus bloques se unen. Por ello, con tablas acotadas por tamaños reales y un número constante de estados, el total es O(n²), no O(n³). Guardar todas las tablas puede consumir O(n²) memoria; liberarlas tras incorporarlas reduce memoria según la organización. Practica cadenas y estrellas, mide transiciones y compara contra enumerar subconjuntos cuando n≤15.`)
    ],q('¿Por qué no hay necesariamente n³ transiciones al combinar subárboles?', ['Porque todo árbol tiene altura logarítmica','Porque cada pareja de objetos se junta por primera vez una sola vez','Porque cada tabla tiene longitud dos'],1,'Usando tamaños reales, la suma de productos de tamaños de bloques se carga a pares de objetos y es O(n²).')),

  a('dp-broken-profile','DP de perfiles: una frontera pequeña en una cuadrícula','Cuenta colocaciones recorriendo celdas y recordando solamente lo que cruza la frontera.',
    ['usaco-gold-dp-bitmasks','usaco-gold-paths-grids'],['Definir una máscara de frontera sin ambigüedad','Reducir una dimensión grande a pasos de una DP'],[
      s('La anchura importa más que el área',`Una cuadrícula puede tener miles de columnas y solo ocho filas. Enumerar configuraciones de todas sus celdas es imposible, pero al recorrer columnas solo importa cómo las decisiones anteriores afectan la siguiente frontera. Una máscara de w bits puede indicar qué posiciones ya están ocupadas por piezas que cruzan desde celdas procesadas. El objetivo es que toda información del pasado relevante para el futuro esté representada allí. Si hay restricciones de conectividad, una simple máscara de ocupación puede ser insuficiente.`),
      s('Colocar dominós sin repetir',`Recorre celdas por columnas y dentro de cada columna por filas. Si la celda actual ya está ocupada, consume esa marca y avanza. Si está libre, intenta un dominó vertical cuando la siguiente fila existe y está libre; también un horizontal cuando queda otra columna, marcando que esa fila estará ocupada al llegar allí. Define antes qué significa cada bit durante una frontera parcialmente procesada: parte corresponde a la columna actual y parte a la próxima. Esa mezcla explica el nombre de perfil roto.`),
      s('Un tablero de dos por tres',`Con dos filas y tres columnas hay tres recubrimientos: tres dominós verticales; dos horizontales en las primeras dos columnas y uno vertical al final; o uno vertical inicial y dos horizontales después. Al comenzar, la máscara es cero. Una columna con dos horizontales salientes produce máscara 11; la siguiente debe consumir ambas marcas y regresar a cero. La respuesta final acepta únicamente máscara cero: cualquier bit pendiente correspondería a una pieza que sale del tablero.`),
      s('Costo y ampliaciones',`Con procesamiento celda a celda y un número constante de transiciones por estado, la versión de dominós cuesta O(h·w·2^w), tomando w como la dimensión pequeña y h como la otra, y O(2^w) memoria con capas rodantes. Si precalculas transiciones de columna, cuenta cuántas parejas de máscaras realmente generas: no prometas automáticamente la misma cota. Practica obstáculos y tableros de área impar, que deben dar cero. Para contar caminos conectados, investiga perfiles con etiquetas de componentes y normalización de etiquetas equivalentes.`)
    ],q('¿Qué máscara se acepta después de procesar toda la cuadrícula?', ['Cualquier máscara','La máscara de todos unos','Cero'],2,'Un bit pendiente indica ocupación que cruza hacia celdas inexistentes; un recubrimiento completo termina sin compromisos abiertos.')),

  a('dp-more','Más técnicas de DP: Knuth y componentes','Aprovecha monotonía de particiones y cuenta estructuras según sus bloques abiertos.',
    ['usaco-gold-dp-ranges','usaco-plat-dc-dp','usaco-gold-combo'],['Verificar las hipótesis de optimización de Knuth','Construir estados basados en componentes parciales'],[
      s('Recurrencias de partición',`Considera dp[l][r]=cost(l,r)+min(l≤k<r){dp[l][k]+dp[k+1][r]}, con dp[i][i]=0. Probar todos los k cuesta O(n³). Knuth permite limitar k a [opt[l][r−1],opt[l+1][r]] cuando la función de costo satisface condiciones suficientes: monotonía al incluir intervalos y desigualdad cuadrangular. Para a≤b≤c≤d se requiere cost(b,c)≤cost(a,d) y cost(a,c)+cost(b,d)≤cost(a,d)+cost(b,c). Estas hipótesis deben demostrarse para el costo real, incluidos sus signos.`),
      s('Fusión de montones',`Con montones de tamaños [2,3,4], fusionar adyacentes paga la suma del bloque resultante. Las sumas de intervalo son no negativas, satisfacen las condiciones anteriores y se obtienen con prefijos. Primero tenemos dp[0][1]=5 y dp[1][2]=7. Para unir los tres, cortar después del primero cuesta 0+7+9=16 y cortar después del segundo cuesta 5+0+9=14. Guardamos el corte óptimo. Con una regla consistente de desempate, los límites óptimos permiten un total O(n²) y memoria O(n²).`),
      s('DP por componentes parciales',`Otra técnica construye una permutación o estructura añadiendo elementos en un orden controlado y recordando cuántos bloques quedan. Un elemento nuevo puede abrir un bloque, extender uno existente o unir dos: el conteo cambia por +1,0 o −1. El estado puede ser dp[i][c] y necesitar indicadores de extremos especiales. Las multiplicidades dependen de qué lados se pueden usar y de si los bloques tienen orientación; no existe un factor universal que puedas copiar a todos los problemas.`),
      s('Construye antes una versión lenta',`Para Knuth, calcula opt completo en casos pequeños y comprueba la monotonía observada, pero recuerda que la experimentación no sustituye la prueba. Incluye costos negativos para descubrir cuándo deja de aplicar el ejemplo de montones. Para componentes, enumera permutaciones de cuatro elementos y agrúpalas por tu estado: si dos configuraciones con el mismo estado admiten distintas transiciones, te falta información. Un estado O(n²) con un número constante de transiciones cuesta O(n²); factores adicionales de extremos o presupuesto multiplican esa cota.`)
    ],q('¿Qué debes justificar antes de aplicar Knuth?', ['Que n sea potencia de dos','Las propiedades del costo que garantizan monotonía de opt','Que todos los cortes den el mismo costo'],1,'La restricción de candidatos solo es válida bajo las condiciones de monotonía; de otro modo puede excluir el corte óptimo.')),

  a('max-flow','Flujo máximo y redes residuales','Modela cantidades que atraviesan una red y permite deshacer elecciones anteriores.',
    ['usaco-gold-unweighted-shortest-paths','usaco-gold-shortest-paths'],['Mantener capacidad y conservación','Explicar caminos aumentantes y Dinic'],[
      s('Lo que significa enviar flujo',`Una red dirigida tiene una fuente s, un sumidero t y capacidad no negativa en cada arista. Un flujo respeta capacidades y conserva cantidad en todos los vértices intermedios: lo que entra debe salir. Queremos maximizar la cantidad neta que sale de s. El modelo sirve para emparejamientos bipartitos, transporte y reparto de recursos. Conviene dibujar qué representa cada unidad y cada capacidad antes de construir el algoritmo: la mayoría de los errores iniciales están en la reducción.`),
      s('La red que permite arrepentirse',`Para una arista u→v de capacidad c y flujo f, la red residual ofrece c−f unidades hacia delante y f hacia atrás. Una arista inversa no transporta mágicamente recursos contra las reglas: cancela parte de una elección previa. Si hay un camino residual s→t, aumenta por su capacidad mínima. Al actualizar la arista directa y su pareja inversa, preservas conservación. Guarda índices inversos explícitos para distinguir aristas paralelas y aristas originales en ambas direcciones.`),
      s('Ejemplo y niveles de Dinic',`Si s→a tiene capacidad 3, s→b capacidad 2, a→t capacidad 2 y b→t capacidad 4, el flujo máximo es 4: salen dos por cada rama. Aunque la fuente dispone de cinco unidades, la rama de a se limita a dos. Dinic hace BFS para asignar niveles residuales y después envía un flujo bloqueante usando únicamente aristas que avanzan un nivel. Los punteros de arista actual evitan explorar repetidamente conexiones que ya no pueden aportar en esa fase.`),
      s('Cotas y verificación',`Dinic general tiene cota O(V²E) y memoria O(V+E); redes especiales pueden admitir mejores cotas, pero deben justificarse. Con capacidades enteras, los aumentos conservan integralidad, útil para interpretar unidades como asignaciones. Practica emparejamiento entre estudiantes y talleres, con capacidades uno en sus enlaces. Al finalizar, comprueba conservación y límites de cada arista y compara redes pequeñas con enumerar cortes. No uses un infinito que desborde al sumar; basta un límite superior seguro del flujo total posible.`)
    ],q('¿Qué representa una capacidad residual inversa de 5?', ['Una capacidad original obligatoria de 5','La posibilidad de cancelar hasta 5 unidades de flujo previo','Un ciclo negativo'],1,'El residual inverso permite revisar decisiones sin violar el flujo original; su capacidad coincide con la cantidad cancelable.')),

  a('min-cut','Corte mínimo y modelos de decisión','Transforma conflictos y costos de selección en una separación entre fuente y sumidero.',
    ['usaco-adv-max-flow'],['Recuperar un corte a partir del residual','Modelar costos y restricciones con aristas'],[
      s('Separar dos lados',`Un corte divide los vértices en S y T, con la fuente en S y el sumidero en T. Su capacidad suma solamente las aristas dirigidas de S hacia T. Cualquier flujo debe atravesar esa frontera, por lo que su valor no puede superar la capacidad del corte. El teorema de flujo máximo y corte mínimo afirma que existe un corte cuya capacidad coincide con el mayor flujo. No sumes automáticamente también las aristas de T hacia S.`),
      s('Encontrar el certificado',`Después de calcular flujo máximo, recorre desde s las aristas con capacidad residual positiva. Los vértices alcanzados forman S; t queda fuera, pues de lo contrario todavía habría un camino aumentante. Las aristas originales de S a T están saturadas. Esta partición es un certificado verificable: suma sus capacidades originales y comprueba que igualan el flujo. La arista inversa residual puede hacer alcanzable un vértice, por eso debes recorrer todo el residual y no únicamente aristas originales.`),
      s('Seleccionar proyectos con dependencias',`Un proyecto rentable de beneficio p recibe una arista s→v de capacidad p; uno con costo c recibe v→t de capacidad c. Si elegir u obliga a elegir v, añade u→v con capacidad M mayor que la suma de beneficios positivos. Interpretamos S como proyectos elegidos. Cortar una ganancia significa renunciar a ella y cortar un costo significa pagarlo. Si A gana 8, B cuesta 3 y A exige B, elegir ambos deja 5; el corte mínimo cuesta 3 frente a la ganancia total 8.`),
      s('Modelos y límites',`La reducción agrega O(V+E) tamaño y su costo dominante es el algoritmo de flujo utilizado. M no necesita ser infinito matemático: un valor seguro superior a cualquier corte admisible evita que se viole una obligación. Practica también cobertura mínima de vértices en grafos bipartitos: después de un emparejamiento máximo, la búsqueda alternante permite recuperar la cobertura. No todo problema binario es automáticamente un corte mínimo; interacciones que no respetan la estructura apropiada pueden requerir otro modelo. Verifica tu reducción enumerando todas las elecciones de cuatro proyectos.`)
    ],q('Tras flujo máximo, ¿qué conjunto define un lado de un corte mínimo?', ['Los vértices de grado par','Los alcanzables desde s por aristas residuales positivas','Los visitados en el primer BFS solamente'],1,'Si t fuera alcanzable habría un aumento; el conjunto residual final determina una frontera cuya capacidad iguala al flujo.')),

  a('flow-lb','Flujo con cotas inferiores','Exige cantidades mínimas por arista y convierte el problema en una circulación factible.',
    ['usaco-adv-max-flow','usaco-adv-min-cut'],['Traducir mínimos a balances por vértice','Comprobar factibilidad saturando demandas auxiliares'],[
      s('Capacidad mínima y máxima',`En algunos repartos no basta con imponer un máximo: cada taller debe recibir entre dos y cinco estudiantes. Para una arista e, exigimos l[e]≤f[e]≤u[e]. Escribe f[e]=l[e]+g[e], donde 0≤g[e]≤u[e]−l[e]. Los mínimos ya colocados pueden romper conservación. Por eso calculamos balance b[v]=suma de mínimos entrantes−suma de mínimos salientes; el flujo adicional debe satisfacer salida(g)−entrada(g)=b[v]. Esta ecuación fija los signos y evita memorizar una receta al revés.`),
      s('Una fuente y un sumidero auxiliares',`Construye las aristas originales con capacidad u−l. Si b[v]>0, agrega S→v de capacidad b[v]: v recibió exceso por los mínimos y debe enviarlo por la red original. Si b[v]<0, agrega v→T de capacidad −b[v]. Ejecuta flujo máximo de S a T. Existe circulación factible si todas las aristas que salen de S se saturan. Luego recuperas cada flujo original como l+g. La suma de balances es cero, así que oferta y demanda auxiliares coinciden.`),
      s('Ejemplo y flujo entre extremos',`En el ciclo a→b→a, exige al menos 2 en a→b y permite hasta 4; la arista de regreso permite hasta 3. Los balances son b[a]=−2 y b[b]=2. Añadimos S→b y a→T, ambas de capacidad 2, y enviamos dos unidades por b→a. Recuperamos una circulación con dos en cada sentido. Para un problema original con fuente s y sumidero t, añade primero una arista t→s de capacidad suficientemente grande para convertir el flujo buscado en circulación.`),
      s('Optimizar después de encontrar factibilidad',`La transformación usa O(V+E) tamaño adicional, por lo que conserva el orden de complejidad del algoritmo de flujo elegido. Para maximizar un flujo s→t con mínimos, encuentra una solución factible, retira la red auxiliar y la arista artificial correctamente y aumenta de s a t en el residual original, incluyendo la posibilidad de cancelar flujo. El flujo inicial de t→s contribuye al valor base. Practica una instancia imposible y revisa cuál demanda quedó sin saturar; nunca confundas satisfacer algunas cotas con conservar flujo en todos los vértices.`)
    ],q('Si b[v]=entrada mínima−salida mínima es positivo, ¿qué arista auxiliar agregas?', ['v→T','S→v','s→t'],1,'v tiene exceso inicial y debe enviar flujo adicional por aristas originales; S→v proporciona esa cantidad en la red auxiliar.')),

  a('min-cost-flow','Flujo de costo mínimo','Envía una cantidad requerida eligiendo rutas y revisando asignaciones mediante costos residuales.',
    ['usaco-adv-max-flow','usaco-adv-sp-neg'],['Asignar costos opuestos a aristas inversas','Usar potenciales en caminos aumentantes de menor costo'],[
      s('Cantidad y precio son objetivos distintos',`Cada arista tiene capacidad y costo por unidad. Buscamos enviar F unidades al menor costo, o maximizar primero el flujo y minimizar después su costo. Debes aclarar cuál de esas variantes exige el problema: enviar cero puede ser lo más barato si no se impone cantidad. En un emparejamiento de tareas y personas, las capacidades uno restringen las asignaciones, mientras los costos representan tiempo, distancia o penalizaciones de elegir cierta pareja.`),
      s('El residual también lleva costos',`Si una arista directa cuesta c, su inversa residual cuesta −c, porque cancelar una unidad devuelve su costo. Un algoritmo de caminos aumentantes elige una ruta s→t residual de menor costo y envía el máximo posible hasta cumplir F o saturar alguna arista. En el ejemplo s→a→t de costo unitario 7 y capacidad 2, y s→b→t de costo unitario 3 y capacidad 1, enviar dos unidades cuesta 3+7=10. Las inversas permiten cambiar una asignación previa cuando aparece una combinación mejor.`),
      s('Dijkstra con potenciales',`Las inversas pueden tener costo negativo. Usa potenciales h con costos reducidos c'(u,v)=c(u,v)+h[u]−h[v] no negativos en la región relevante. Si inicialmente hay costos negativos, Bellman–Ford puede construirlos cuando no existen ciclos negativos alcanzables. Tras Dijkstra, aumenta h[v] con la distancia reducida para los vértices alcanzables. Las rutas conservan su orden de costos por cancelación telescópica. No actualices potenciales de vértices cuya distancia sea infinito, y calcula el costo final con costos originales o con la conversión de potenciales correcta.`),
      s('Hipótesis, costo y práctica',`Con A aumentos, heap binario y una inicialización Bellman–Ford, el costo es O(VE+A(E+V) log V). Con capacidades enteras y demanda F, A≤F, aunque puede ser una cota grande si F es enorme. La versión sencilla supone que no hay ciclos negativos residuales aprovechables al iniciar; problemas con circulaciones de costo negativo requieren tratamiento adicional. Practica asignaciones pequeñas enumerando permutaciones y verifica cantidad y costo, no solo factibilidad. Usa enteros anchos para capacidad·costo y distingue no alcanzar F de encontrar un costo alto.`)
    ],q('Si enviar por u→v cuesta 4, ¿cuánto cuesta su inversa residual?', ['4','0','−4'],2,'Cancelar una unidad recupera exactamente las cuatro unidades de costo pagadas; por eso el costo inverso es opuesto.')),

  a('fft','FFT, NTT y convolución','Multiplica polinomios transformando coeficientes en evaluaciones y regresando después.',
    ['usaco-gold-modular','usaco-gold-combo'],['Reconocer una convolución en un conteo','Elegir una longitud y un dominio de transformación válidos'],[
      s('El producto es una suma de parejas',`Si A(x)=suma a[i]x^i y B(x)=suma b[j]x^j, su producto tiene coeficiente c[k]=suma(i+j=k)a[i]b[j]. Esta operación se llama convolución. Por ejemplo, [1,2] convolucionado con [3,4] da [3,10,8], porque (1+2x)(3+4x)=3+10x+8x². También cuenta sumas: si a[i] y b[j] son frecuencias de valores, c[k] cuenta parejas cuya suma es k. El algoritmo directo cuesta O(nm).`),
      s('Evaluar, multiplicar, interpolar',`Un polinomio queda determinado por suficientes evaluaciones distintas. FFT evalúa en raíces de la unidad aprovechando que los coeficientes pares e impares forman dos polinomios menores: A(x)=A_par(x²)+x·A_impar(x²). Las mismas evaluaciones de x² sirven para x y −x, produciendo las mariposas. Tras multiplicar punto a punto las evaluaciones de A y B, la transformada inversa recupera c. Para evitar que grados altos se envuelvan circularmente, rellena con ceros hasta una potencia de dos N≥n+m−1.`),
      s('Aritmética compleja o modular',`La FFT compleja introduce redondeo: recuperar enteros redondeando funciona solo si el error está controlado respecto de magnitudes y longitud. La NTT usa raíces módulo un primo p; para longitud N requiere N divisor de p−1 y una raíz de orden N. Por ejemplo, 998244353 admite potencias de dos hasta 2^23. La inversa usa raíces inversas y multiplica por N⁻¹ módulo p. Obtener un resultado entero grande puede requerir varios primos y reconstrucción mediante el teorema chino del resto.`),
      s('Costo y pruebas',`La recurrencia T(N)=2T(N/2)+O(N) da O(N log N) tiempo y O(N) memoria en implementaciones iterativas. La normalización de la inversa, el signo de raíces y la permutación de bits deben ser consistentes entre ambas transformadas. Practica multiplicando arreglos de tamaño hasta treinta y compara con doble bucle. Incluye ceros, coeficientes negativos normalizados módulo p y grados justo por encima de una potencia de dos. Antes de aplicar FFT a una DP, demuestra que la transición es una convolución y no otra operación parecida como min-plus.`)
    ],q('Para longitudes 5 y 7, ¿qué longitud potencia de dos evita convolución circular?', ['8','16','4'],1,'El producto tiene 5+7−1=11 coeficientes; la siguiente potencia de dos suficiente es 16.')),

  a('fft-ext','Series formales y operaciones avanzadas con polinomios','Construye inversas, logaritmos y funciones generadoras encima de una multiplicación rápida.',
    ['usaco-adv-fft','usaco-gold-modular'],['Derivar el paso de Newton para invertir una serie','Relacionar operaciones algebraicas con conteos'],[
      s('Trabajar módulo x^n',`Una serie formal se maneja por sus coeficientes, sin necesitar que converja como función real. Escribir A·B≡1 módulo x^n significa que los primeros n coeficientes del producto son [1,0,…,0]. A tiene inversa si su término constante es invertible en el campo elegido. Para A=1−x, la inversa truncada hasta grado tres es 1+x+x²+x³: al multiplicar queda 1−x⁴, indistinguible de 1 cuando descartamos grados desde cuatro.`),
      s('Duplicar precisión con Newton',`Supón que B aproxima A⁻¹ módulo x^m. Define B_nuevo=B·(2−A·B) y trunca módulo x^(2m). Si A·B=1−E y E empieza en grado m, entonces A·B_nuevo=(1−E)(1+E)=1−E²; el error empieza en grado 2m. Cada iteración duplica los coeficientes correctos. Con multiplicación M(n)=O(n log n), la suma del trabajo de tamaños duplicados es O(n log n), además de O(n) memoria con una implementación cuidadosa.`),
      s('Una caja de operaciones relacionadas',`La identidad (log A)'=A'/A permite logaritmos cuando A[0]=1; integra A'·A⁻¹. La exponencial se obtiene mediante Newton para resolver log B=A y exige A[0]=0. Raíces cuadradas requieren una raíz del término constante y condiciones sobre el campo, especialmente invertibilidad de 2. División polinómica puede reducirse a inversión tras invertir el orden de coeficientes. Evaluación multipunto e interpolación usan árboles de productos y suelen costar O(M(n) log n). No son operaciones válidas sin revisar términos constantes y divisiones modulares.`),
      s('Funciones generadoras y variantes',`Si puedes tomar cualquier número de objetos de tamaño d, la serie 1/(1−x^d) describe sus cantidades; el producto para d=1…n cuenta particiones enteras en sus coeficientes. Factores 1+x^d representan usar cada objeto a lo sumo una vez. Practica construyendo coeficientes pequeños con mochila y comparándolos con el producto. Para combinaciones cuyo índice se une con XOR, necesitas transformada de Walsh–Hadamard, no FFT ordinaria. Sus mariposas de suma y diferencia trabajan sobre máscaras y cuestan O(k·2^k), con una normalización inversa compatible con el módulo.`)
    ],q('¿Por qué B(2−AB) duplica precisión al invertir A?', ['Porque duplica todos los coeficientes','Porque el nuevo error es el cuadrado del anterior','Porque elimina los términos pares'],1,'Si AB=1−E, entonces A·B(2−AB)=(1−E)(1+E)=1−E²; el grado mínimo del error se duplica.')),

  a('string-search','Buscar patrones: KMP, Z, palíndromos y Aho–Corasick','Elige una estructura según busques un patrón, muchos patrones o simetrías en una cadena.',
    ['usaco-gold-hashing','usaco-gold-stacks'],['Reutilizar coincidencias sin comparar desde cero','Distinguir búsqueda de patrones y búsqueda de palíndromos'],[
      s('Un patrón y los bordes de sus prefijos',`KMP calcula pi[i], longitud del mayor prefijo propio que también es sufijo de s[0..i]. Si la próxima letra falla después de j coincidencias, intenta j=pi[j−1] en vez de reiniciar o retroceder en el texto. Para el patrón aba, pi=[0,0,1]; tras encontrarlo en ababa, el borde a permite hallar la aparición solapada que empieza en dos. El invariante conserva el mayor prefijo del patrón que coincide con el sufijo del texto procesado.`),
      s('Programa de KMP y función Z',`El programa imprime 0 y 2 al buscar aba en ababa. Funciona para un patrón no vacío y conserva coincidencias superpuestas. La función Z ofrece otra representación: z[i] es la longitud del prefijo completo que coincide al comenzar en i. Mantiene una ventana [l,r) de coincidencia conocida para reutilizar comparaciones. Ambas funciones se calculan en O(n); para usar Z con patrón y texto, concatena patrón, separador ausente del alfabeto y texto. No inventes un separador que pueda aparecer en los datos.`, String.raw`#include <iostream>
#include <string>
#include <vector>
using namespace std;
int main(){
  string p="aba",t="ababa";
  vector<int> pi(p.size());
  for(int i=1;i<(int)p.size();++i){
    int j=pi[i-1];
    while(j>0 && p[i]!=p[j]) j=pi[j-1];
    if(p[i]==p[j]) ++j;
    pi[i]=j;
  }
  int j=0;
  for(int i=0;i<(int)t.size();++i){
    while(j>0 && t[i]!=p[j]) j=pi[j-1];
    if(t[i]==p[j]) ++j;
    if(j==(int)p.size()){
      cout<<i-j+1<<'\n'; j=pi[j-1];
    }
  }
}`),
      s('Palíndromos: Manacher y eertree',`Manacher guarda radios de palíndromos pares e impares y reutiliza el reflejo respecto del centro del palíndromo más a la derecha. Calcula todos los radios en O(n), evitando expandir desde cero en cada centro. En abacaba, el centro índice tres tiene radio impar cuatro, contando la letra central. Un árbol palindrómico o eertree guarda cada palíndromo distinto como nodo y enlaces al mayor sufijo palindrómico propio; tiene O(n) nodos. Sus raíces de longitud cero y menos uno simplifican insertar letras y tratar paridades.`),
      s('Muchos patrones: trie y enlaces de fallo',`Un trie comparte prefijos de un diccionario. Aho–Corasick añade enlaces de fallo hacia el mayor sufijo del estado que también es prefijo de algún patrón. Procesando he y she, encontrar she también debe reportar he; los enlaces de salida manejan coincidencias terminales sin perder sufijos. Para alfabeto fijo y transiciones completas, construir cuesta O(L·σ) y buscar O(texto+ocurrencias), con L longitud total de patrones. Transiciones dispersas cambian las cotas según el contenedor. Practica patrones repetidos, patrones que contienen otros y cadenas formadas por una sola letra.`),
      s('Comprobar el algoritmo adecuado',`KMP y Z usan O(n) memoria para sus tablas; Manacher también. Un trie de arreglos densos puede gastar mucha memoria si σ es grande, aunque sus búsquedas sean rápidas. El número de ocurrencias que solicitas imprimir puede ser cuadrático incluso con un algoritmo óptimo, de modo que distingue contar de enumerar. Antes de integrar una plantilla, compara todas las coincidencias y palíndromos de cadenas cortas con doble bucle. Define si las posiciones son bytes o caracteres: los problemas habituales usan alfabetos simples, mientras UTF-8 requiere otra interpretación.`)
    ],q('Después de encontrar aba en ababa, ¿por qué KMP conserva j=1?', ['Para omitir todas las coincidencias solapadas','Porque a es un borde propio de aba','Porque todos los patrones tienen borde uno'],1,'El sufijo a de la coincidencia completa ya es el prefijo a del siguiente candidato, y permite encontrar la aparición en posición dos.')),

  a('suffix-array','Arreglos de sufijos y prefijos comunes','Ordena todos los sufijos para buscar cadenas y contar subcadenas distintas.',
    ['usaco-gold-hashing','usaco-plat-dc-srq'],['Construir rangos mediante duplicación','Usar LCP para contar y comparar subcadenas'],[
      s('Ordenar comienzos de cadenas',`El arreglo de sufijos SA contiene posiciones ordenadas por el texto que comienza en cada una y llega hasta el final. Para banana, el orden es [5,3,1,0,4,2]: a, ana, anana, banana, na, nana. Guardamos posiciones, no copias de sufijos, porque copiarlos costaría memoria cuadrática. Los sufijos que empiezan con un mismo patrón quedan juntos; dos búsquedas binarias delimitan ese bloque. Si cada comparación recorre el patrón, el costo básico es O(|patrón| log n).`),
      s('Duplicar lo que sabemos comparar',`Inicialmente ordena por un carácter y asigna rangos iguales a caracteres iguales. En la ronda k, cada sufijo se representa por el par de rangos de sus primeros 2^k caracteres y los siguientes 2^k; una parte que sale del texto usa un centinela menor. Ordenar esos pares produce rangos para prefijos de longitud 2^(k+1). Tras O(log n) rondas se distinguen todos los sufijos. Con sort comparativo, construir cuesta O(n log² n); con radix o counting sort por rangos, O(n log n).`),
      s('LCP y conteo de subcadenas',`LCP[i] mide el prefijo común entre SA[i−1] y SA[i]. Para banana, los LCP consecutivos son [1,3,0,0,2]. Hay n(n+1)/2=21 subcadenas por posición; restamos la suma de LCP, que es seis, y obtenemos quince subcadenas distintas. Cada sufijo aporta todos sus prefijos excepto los ya presentes en su predecesor lexicográfico. Kasai calcula LCP en O(n) reutilizando que, al avanzar una posición, una coincidencia conocida pierde como máximo un carácter.`),
      s('Consultas y detalles prácticos',`El LCP de dos sufijos cualesquiera es el mínimo de los LCP consecutivos entre sus posiciones en SA. Una estructura RMQ permite responderlo rápido después del preprocesamiento. Si añades un carácter terminador, debe ser único y ordenarse como esperas; exclúyelo de conteos del texto original. Practica con aaaa, donde los sufijos tienen muchas coincidencias, y con caracteres todos distintos. Verifica SA contra ordenar índices con comparación directa para n pequeño. Para varias cadenas concatenadas, usa separadores apropiados y evita contar subcadenas que atraviesen sus fronteras.`)
    ],q('¿Cuántas subcadenas distintas tiene banana según sus LCP?', ['21','14','7'],1,'Hay 6·7/2=21 subcadenas por posición y la suma de LCP es 7; quedan 21−7=14 distintas.')),

  a('string-suffix','Autómatas y árboles de sufijos','Representa todas las subcadenas de un texto con una estructura de tamaño lineal.',
    ['usaco-adv-suffix-array','usaco-adv-string-search'],['Interpretar estados y enlaces de un autómata de sufijos','Comparar autómata, árbol y arreglo de sufijos'],[
      s('Agrupar por lugares de terminación',`Un autómata de sufijos agrupa subcadenas con el mismo conjunto de posiciones finales. Cada estado v tiene len[v], la mayor longitud representada, y link[v], hacia la clase del mayor sufijo propio que cambia de conjunto de terminaciones. Las longitudes de su clase van de len[link[v]]+1 a len[v]. Desde el estado inicial, cada camino etiqueta una subcadena distinta del texto. Este significado es más útil que memorizar una rutina de construcción: explica conteos, pertenencia y propagación de ocurrencias.`),
      s('Extender y clonar',`Al añadir una letra, creamos el estado correspondiente al nuevo prefijo completo y actualizamos transiciones faltantes siguiendo enlaces de sufijo. Si encontramos una transición hacia un estado cuya longitud no encaja con la nueva clase, creamos un clon con sus transiciones y enlace, pero con longitud reducida. Redirigimos las transiciones necesarias y ajustamos enlaces. El clon separa clases que antes compartían terminaciones; no representa por sí mismo una nueva aparición del texto, por eso su contador inicial de ocurrencias es cero.`),
      s('Contar en un ejemplo pequeño',`El texto aba tiene subcadenas distintas a, b, ab, ba y aba: cinco. En el autómata, suma len[v]−len[link[v]] sobre todos los estados no iniciales para obtener ese conteo. Para frecuencias, asigna uno a los estados creados por cada prefijo y propaga conteos en orden decreciente de len hacia link. Así a tiene dos ocurrencias, mientras ab tiene una. Para la mayor subcadena común de dos textos, recorre el segundo sobre el autómata del primero y usa enlaces cuando falla una transición.`),
      s('Árboles comprimidos y límites',`Un árbol de sufijos comprime caminos de un trie de todos los sufijos; sus aristas guardan intervalos del texto, evitando copiar etiquetas. Ukkonen lo construye online mediante punto activo y enlaces de sufijo, pero sus invariantes merecen estudio separado. Con alfabeto fijo, autómata y árbol tienen construcción O(n) y memoria O(n); mapas ordenados añaden factores logarítmicos según el alfabeto. SA más LCP ofrece otra representación y permite construir relaciones de árbol. Practica comparando conteos con un set de todas las subcadenas para n pequeño y usa separadores al combinar textos.`)
    ],q('¿Cuántas longitudes de subcadena representa un estado v no inicial?', ['len[v]','len[v]−len[link[v]]','len[link[v]]+1'],1,'Las longitudes forman el intervalo entero desde len[link[v]]+1 hasta len[v], cuya cantidad es la diferencia.')),

  a('extend-euclid','Euclides extendido, ecuaciones e inversos','Encuentra coeficientes de Bézout y decide cuándo una ecuación entera tiene solución.',
    ['usaco-gold-divisibility','usaco-gold-modular'],['Obtener x e y con ax+by=gcd(a,b)','Resolver congruencias sin suponer módulo primo'],[
      s('El máximo común divisor trae un certificado',`Euclides calcula gcd(a,b) sustituyendo (a,b) por (b,a mod b). La versión extendida también obtiene enteros x e y que satisfacen ax+by=g. Esa identidad es un certificado comprobable con una multiplicación y una suma. Para 30 y 18, g=6 y una solución es x=−1,y=2 porque −30+36=6. Los coeficientes pueden ser negativos aunque ambos números de entrada sean positivos; no deben guardarse en tipos sin signo.`),
      s('Derivar la vuelta recursiva',`Si la llamada pequeña encuentra b·x1+(a mod b)·y1=g, sustituye a mod b=a−floor(a/b)·b. Obtenemos a·y1+b·(x1−floor(a/b)·y1)=g. Por tanto x=y1 e y=x1−(a/b)·y1. El caso base b=0 devuelve g=a,x=1,y=0 para a positivo. El programa usa entradas positivas de magnitud moderada; para enteros cercanos al límite hay que comprobar productos intermedios y normalizar signos de manera explícita.`, String.raw`#include <iostream>
#include <tuple>
using namespace std;
tuple<long long,long long,long long> egcd(long long a,long long b){
  if(b==0) return {a,1,0};
  auto [g,x1,y1]=egcd(b,a%b);
  return {g,y1,x1-(a/b)*y1};
}
int main(){
  auto [g,x,y]=egcd(30,18);
  cout<<g<<' '<<x<<' '<<y<<'\n';
  cout<<30*x+18*y<<'\n';
}`),
      s('Ecuaciones y congruencias',`La ecuación ax+by=c tiene solución entera exactamente cuando g divide c. Multiplica los coeficientes de Bézout por c/g para obtener una solución (x0,y0); todas son x=x0+t·b/g, y=y0−t·a/g. Un inverso de a módulo m existe si gcd(a,m)=1 y se obtiene de x normalizado a [0,m). Por ejemplo 3·4−11=1, así que 4 es el inverso de 3 módulo 11. No necesitas que m sea primo.`),
      s('Combinar condiciones y practicar',`Para congruencias x≡r1 mod m1 y x≡r2 mod m2, existe solución si gcd(m1,m2) divide r2−r1. Euclides extendido permite resolver el desplazamiento y la nueva periodicidad es lcm(m1,m2). El algoritmo tarda O(log min(a,b)) divisiones para entradas positivas y usa esa profundidad si es recursivo. Practica restricciones adicionales x≥0,y≥0 ajustando el intervalo de t; con negativos, división entera de C++ trunca hacia cero y no equivale siempre a piso matemático. Comprueba cada respuesta sustituyéndola en la ecuación original.`)
    ],q('¿Tiene solución entera 6x+10y=7?', ['Sí, por Bézout','No, porque 2 no divide 7','Solo con x negativo'],1,'gcd(6,10)=2 y cualquier combinación entera es par; siete no es múltiplo del máximo común divisor.')),

  a('catalan','Números de Catalan y estructuras balanceadas','Cuenta paréntesis, árboles y caminos mediante una descomposición única.',
    ['usaco-gold-combo','usaco-gold-intro-dp'],['Derivar la recurrencia de Catalan','Distinguir conteo exacto y modular'],[
      s('Una familia de conteos',`Los números de Catalan cuentan, entre otras cosas, secuencias de n pares de paréntesis correctamente balanceados, árboles binarios ordenados con n nodos internos y triangulaciones de un polígono convexo de n+2 vértices. Estos objetos comparten una descomposición recursiva. No basta identificar que algo parece un árbol: el orden de hijos, la definición de tamaño y las restricciones cambian el conteo. Comienza siempre por construir una correspondencia concreta entre los objetos del problema y una familia conocida.`),
      s('Separar el primer par',`Una secuencia no vacía tiene una forma única (A)B, donde A contiene i pares y B contiene n−1−i. Como elegimos A y B independientemente, C[n]=suma(i=0…n−1)C[i]·C[n−1−i], con C[0]=1. El uno del caso vacío es esencial: permite que A o B estén vacíos. Calculamos C[1]=1, C[2]=2 y C[3]=C[0]C[2]+C[1]C[1]+C[2]C[0]=2+1+2=5. El programa implementa esa recurrencia directamente.`, String.raw`#include <iostream>
#include <vector>
using namespace std;
int main(){
  int n=10;
  vector<long long> c(n+1);
  c[0]=1;
  for(int size=1;size<=n;++size)
    for(int left=0;left<size;++left)
      c[size]+=c[left]*c[size-1-left];
  for(int i=0;i<=n;++i) cout<<c[i]<<(i==n?'\n':' ');
}`),
      s('La fórmula y una barrera',`Representa abrir paréntesis como subir y cerrar como bajar. Hay binom(2n,n) caminos con n pasos de cada tipo, pero algunos bajan de altura cero. Una reflexión de los caminos inválidos produce binom(2n,n+1), por lo que C[n]=binom(2n,n)−binom(2n,n+1)=binom(2n,n)/(n+1). Para n=3, 20−15=5. Esta prueba explica qué condición de prefijos hace especial al conteo: igual cantidad total de aperturas y cierres no garantiza balance.`),
      s('Complejidad y aritmética',`La recurrencia tarda O(n²) y usa O(n) memoria; es excelente para validar fórmulas y para módulos donde dividir no resulta sencillo. Con factoriales e inversos sobre un primo apropiado, puedes calcular combinaciones en O(n) preprocesamiento, pero si el módulo divide n+1 no puedes simplemente invertirlo. Los valores exactos crecen rápido y desbordan long long; el ejemplo limita n a diez. Practica generando todos los paréntesis para n≤5, filtrando prefijos negativos y comparando con Catalan. Después explica la correspondencia con árboles usando la misma división izquierda-derecha.`)
    ],q('¿Por qué C[0]=1 en la recurrencia?', ['Porque existen cero estructuras vacías','Porque hay una elección de estructura vacía','Porque mejora la complejidad'],1,'La estructura vacía es una posibilidad válida y debe aportar un factor uno cuando una de las dos partes está vacía.')),

  a('xor-basis','Bases XOR y álgebra sobre bits','Resume todos los XOR de subconjuntos mediante vectores linealmente independientes.',
    ['usaco-silver-intro-bitwise','usaco-gold-dp-bitmasks'],['Insertar vectores eliminando su bit principal','Consultar pertenencia y máximo XOR'],[
      s('Los bits como coordenadas',`Un entero de B bits puede verse como un vector sobre el campo de dos elementos. Sumar vectores equivale a XOR, pues 1+1=0. Los XOR de todos los subconjuntos forman un espacio vectorial; una base pequeña genera exactamente las mismas respuestas que el arreglo completo. Guarda como máximo un vector por bit principal. Esta idea no es un trie: el trie organiza números individuales, mientras la base representa combinaciones de muchos números.`),
      s('Inserción por eliminación',`Para insertar x, examina bits de mayor a menor. Si su bit b está prendido y ya existe basis[b], reemplaza x por x XOR basis[b], apagando ese bit sin introducir bits mayores. Si basis[b] está vacío, guarda x y termina. Si x se reduce a cero, era dependiente. Con números 3=011 y 5=101, ambos se guardan; insertar 6=110 produce 6 XOR 5 XOR 3=0. Por tanto, 6 ya era una combinación.`),
      s('Pertenencia, máximo y programa',`Para comprobar si un valor puede formarse, redúcelo con la misma eliminación y acepta si llega a cero. Para maximizar XOR, recorre la base de bits altos a bajos y aplica un vector cuando mejora el valor actual. La independencia de los bits principales garantiza que mejorar el bit más significativo posible no se pierde después. El programa usa enteros sin signo de 64 bits y encuentra máximo seis para {3,5,6}; los XOR posibles son 0,3,5,6.`, String.raw`#include <iostream>
#include <array>
#include <cstdint>
using namespace std;
int main(){
  array<uint64_t,64> basis{};
  for(uint64_t x:{uint64_t(3),uint64_t(5),uint64_t(6)}){
    for(int bit=63;bit>=0;--bit){
      if(((x>>bit)&1)==0) continue;
      if(basis[bit]) x^=basis[bit];
      else {basis[bit]=x;break;}
    }
  }
  uint64_t answer=0;
  for(int bit=63;bit>=0;--bit)
    if((answer^basis[bit])>answer) answer^=basis[bit];
  cout<<answer<<'\n';
}`),
      s('Dimensión y restricciones',`Insertar n valores cuesta O(nB), consultar pertenencia o máximo O(B) y guardar la base O(B). Una base de rango r genera 2^r valores distintos; cada uno aparece en 2^(n−r) subconjuntos de índices si contamos todas las elecciones. Ese número puede necesitar módulo o enteros grandes. La base simple no permite imponer cualquier restricción de posiciones ni eliminar valores arbitrariamente. Practica enumerando todos los subconjuntos de arreglos cortos y compara el conjunto de XOR. Incluye ceros y repetidos para comprobar que dependencia no significa ausencia de elecciones distintas.`)
    ],q('Si tres números tienen rango XOR dos, ¿cuántos XOR distintos generan?', ['3','4','8'],1,'Un espacio de dimensión dos sobre el campo de dos elementos tiene 2²=4 vectores distintos.')),

  a('fracturing-search','Fracturing search: enumerar las mejores soluciones','Parte un espacio enorme en regiones disjuntas y visita primero la mejor candidata de cada región.',
    ['usaco-silver-priority-queues','usaco-gold-mst'],['Diseñar un árbol implícito sin duplicados','Separar costo de enumeración y costo de optimización local'],[
      s('De buscar una solución a buscar las primeras K',`A veces podemos encontrar la solución mínima fácilmente, pero queremos las K mejores entre un número enorme de objetos. Organiza esos objetos como un árbol implícito cuya raíz sea el mínimo y donde cada hijo valga al menos su padre. Una cola de prioridad empieza con la raíz. Extraemos el mejor candidato, lo reportamos y añadimos sus hijos. Toda solución aún no vista queda debajo de algún candidato de la cola, por lo que no puede ser mejor que ese ancestro.`),
      s('La partición debe ser disjunta',`La dificultad está en diseñar los hijos. Deben representar regiones que cubran todas las soluciones restantes sin superponerse. En enumeración de árboles generadores, si el mínimo tiene aristas e1,…,er, una partición válida fija e1,…,e(i−1) como presentes y ei como ausente para el hijo i. Cada otro árbol tiene una primera arista de esa lista que omite. Se vuelve a calcular el mínimo bajo las restricciones acumuladas. Simplemente prohibir una arista distinta en cada hijo produciría duplicados.`),
      s('Ejemplo: sumas de dos listas',`Con A=[1,4] y B=[2,5], los pares (i,j) tienen valor A[i]+B[j]. Usa raíz (0,0), hijo (i,j+1) si existe y, solo cuando j=0, otro hijo (i+1,0). Así cada par tiene un único padre y el valor no disminuye porque las listas están ordenadas. La cola devuelve 3,6,6,9. Los dos seises corresponden a objetos diferentes y ambos deben contarse si pedimos pares; deduplicar valores cambiaría el problema.`),
      s('Análisis y experimentación',`Con como máximo D hijos por objeto y costo O(1) de generarlos, obtener K objetos cuesta O(KD log(KD)) y O(KD) memoria. Si resolver el óptimo de cada región cuesta T, añade O(KDT); no lo escondas bajo el costo de la cola. Otra opción busca un umbral y cuenta hasta K nodos permitidos, si hay una cota numérica útil. Practica enumerando todos los pares pequeños y comparando su orden. Después prueba árboles generadores de cuatro vértices y demuestra que tu partición los incluye exactamente una vez.`)
    ],q('¿Qué condición evita duplicar soluciones al dividir una región?', ['Que todas las regiones tengan el mismo tamaño','Que los hijos formen subespacios disjuntos','Que todos los valores sean distintos'],1,'La disyunción da un único lugar a cada objeto; valores iguales pueden pertenecer legítimamente a soluciones diferentes.')),

  a('game-theory','Teoría de juegos: estados ganadores, Nim y Grundy','Resuelve juegos imparciales finitos separando estrategia, estados y combinación de componentes.',
    ['usaco-gold-intro-dp','usaco-silver-intro-bitwise'],['Calcular estados ganadores y números de Grundy','Verificar las hipótesis para combinar juegos con XOR'],[
      s('Ganar significa dejar sin respuesta',`Considera un juego de información perfecta donde ambos jugadores tienen los mismos movimientos disponibles, los turnos alternan y pierde quien no puede mover. En un grafo de estados sin ciclos, un estado es ganador si tiene algún movimiento hacia uno perdedor; es perdedor si todos sus movimientos van a estados ganadores. El estado terminal es perdedor. Las reglas importan: si ganar consiste en no poder mover, o hay azar o información oculta, esta recurrencia requiere cambios.`),
      s('Grundy añade una medida combinable',`Define g(s)=mex{g(t): s puede moverse a t}, donde mex es el menor entero no negativo ausente. Un terminal tiene Grundy cero. Si se puede quitar una o dos piedras, los valores para tamaños 0,1,2,3,4 son 0,1,2,0,1. Por ejemplo, desde tres piedras se llega a estados con valores dos y uno; su mex es cero, así que es perdedor. Un valor distinto de cero identifica exactamente los estados ganadores en este modelo.`),
      s('Combinar componentes independientes',`Si en cada turno eliges exactamente un componente y haces un movimiento legal allí, el Grundy de la suma de juegos es el XOR de sus valores. En Nim, quitar cualquier cantidad positiva de una pila da g(tamaño)=tamaño. Para pilas [3,4,5], el XOR es 3 XOR 4 XOR 5=2, así que existe jugada ganadora. Cambiar la pila de tres a uno deja 1 XOR 4 XOR 5=0. La estrategia consiste en devolver siempre un XOR cero al rival.`),
      s('Costo, límites y práctica',`En un DAG explícito, calcular todos los Grundy cuesta O(V+E) si el mex se obtiene marcando valores hasta el grado de salida con una técnica adecuada, y usa O(V+E) memoria. En juegos implícitos, contar estados y movimientos es parte del análisis. No apliques XOR si un movimiento modifica simultáneamente varias componentes, ni uses la regla estándar para Nim misère sin revisar sus excepciones. Practica quitando piedras de un conjunto permitido, descubre períodos experimentalmente y después demuéstralos; observar diez repeticiones no prueba una periodicidad infinita.`)
    ],q('Un estado tiene sucesores con Grundy {0,1,3}. ¿Cuál es su Grundy?', ['0','2','4'],1,'mex es el menor entero no negativo ausente: están cero y uno, pero falta dos.')),

  a('prefix-sums-nt-1','Sumas aritméticas I: cocientes y convolución de Dirichlet','Agrupa divisiones enteras repetidas y convierte identidades de divisores en prefijos rápidos.',
    ['usaco-gold-divisibility','usaco-gold-modular'],['Enumerar intervalos con el mismo cociente','Derivar sumas de divisores y una recurrencia para totientes'],[
      s('Pocos cocientes distintos',`Aunque i recorra de uno a N, floor(N/i) solo toma O(√N) valores distintos. Para i≤√N hay a lo sumo √N índices; después el cociente es menor que √N. Si un bloque comienza en l y q=floor(N/l), termina en r=floor(N/q). Avanza directamente a r+1. Para N=10, los bloques son [1,1] con diez, [2,2] con cinco, [3,3] con tres, [4,5] con dos y [6,10] con uno.`),
      s('Sumar divisores cambiando el orden',`La suma de σ(k) para k≤N puede contar cada divisor d en todos sus múltiplos: S(N)=suma(d=1…N)d·floor(N/d). Agrupando [l,r], la contribución es q·(l+r)(r−l+1)/2. Para N=5, σ vale 1,3,4,7,6 y suma 21; la fórmula alternativa da 1·5+2·2+3·1+4·1+5·1=21. El programa usa N=10 y obtiene 87. Divide uno de los factores pares antes de multiplicar y analiza desbordamiento para límites grandes.`, String.raw`#include <iostream>
using namespace std;
int main(){
  long long n=10,answer=0;
  for(long long l=1;l<=n;){
    long long quotient=n/l,r=n/quotient;
    long long x=l+r,y=r-l+1;
    if(x%2==0) x/=2; else y/=2;
    answer+=quotient*x*y;
    l=r+1;
  }
  cout<<answer<<'\n';
}`),
      s('Convolución y sumas de totientes',`La convolución de Dirichlet es (f*g)(n)=suma(d|n)f(d)g(n/d). Una función multiplicativa cumple f(1)=1 y f(ab)=f(a)f(b) cuando gcd(a,b)=1; no necesariamente para cualquier pareja. La identidad suma(d|n)φ(d)=n implica, al sumar hasta N, suma(k=1…N)Φ(floor(N/k))=N(N+1)/2, donde Φ(x)=suma(i≤x)φ(i). Separa k=1 para obtener Φ(N)=N(N+1)/2−suma(k=2…N)Φ(floor(N/k)). Agrupa cocientes repetidos y memoiza resultados. La función de Möbius es la inversa de la función constante uno bajo esta convolución.`),
      s('Cotas y práctica verificable',`La suma de divisores agrupada tarda O(√N) y usa O(1) memoria. Para la recurrencia memoizada de totientes, no confundas esa cota con el costo total: también calculas muchos argumentos. Sin criba inicial, una cota conservadora es O(N^(3/4)) tiempo y O(√N) resultados para una consulta N, con acceso eficiente a los cocientes; precalcular prefijos pequeños mejora el equilibrio. Practica φ con una criba para N≤1000 y compara cada prefijo. En módulo compuesto, dividir por dos o invertir f(1) exige revisar invertibilidad, no asumir aritmética de campo.`)
    ],q('Para N=20 y l=6, ¿hasta qué r se mantiene floor(N/i)=3?', ['6','7','8'],0,'q=20/6=3 y r=floor(20/3)=6; en i=7 el cociente ya baja a dos.')),

  a('prefix-sums-nt-2','Sumas aritméticas II: contar primos sin llegar a N','Combina una criba dinámica con los O(√N) cocientes necesarios para calcular π(N).',
    ['usaco-adv-prefix-sums-nt-1'],['Mantener conteos filtrados por primos pequeños','Respetar el orden de actualización en una criba comprimida'],[
      s('El objetivo es contar, no listar',`π(N) cuenta primos menores o iguales a N. Una criba hasta N es apropiada cuando cabe en memoria, pero N puede ser tan grande que no podamos guardar cada entero. Para contar solamente, conserva valores v del conjunto {floor(N/i)}. Este conjunto tiene O(√N) elementos y es estable bajo nuevas divisiones enteras: floor(floor(N/i)/p)=floor(N/(ip)). Esa clausura permite consultar los argumentos requeridos por la recurrencia sin crear una tabla de tamaño N.`),
      s('Una criba sobre prefijos',`Inicializa G(v)=v−1, contando enteros de dos a v. Procesa los primos p hasta √N. Para cada v≥p², actualiza G(v)−=G(floor(v/p))−G(p−1), usando valores de la etapa anterior. Los múltiplos nuevos eliminados son p por un factor que sobrevivió a primos menores y es al menos p; restar G(p−1) evita retirar el propio p y productos ya eliminados. Recorre v en orden descendente para que el argumento menor floor(v/p) no haya cambiado todavía en esta etapa.`),
      s('Un conteo completo para diez',`Los valores necesarios son 10,5,3,2,1 y sus G iniciales 9,4,2,1,0. Con p=2, para v=10 restamos G(5)−G(1)=4 y queda 5; para v=5 restamos G(2)−G(1)=1 y queda 3. Con p=3, solo v=10 cumple v≥9: restamos G(3)−G(2)=1 y queda 4. Esos cuatro son 2,3,5,7. Detectamos p primo observando que G(p)>G(p−1) antes de procesarlo.`),
      s('Costo y siguientes pasos',`La implementación básica visita, para cada primo p, solamente los cocientes v≥p². Una cota segura de ese trabajo es O(N^(3/4)) y la memoria O(√N), usando arreglos para indexar valores pequeños y cocientes grandes en O(1); estimaciones más finas aprovechan la densidad de primos. Versiones con cortes adicionales y estructuras Fenwick mejoran el orden, pero requieren otro análisis. Practica comparando todos los N hasta diez mil con Eratóstenes. Evita calcular p*p en un tipo estrecho y corrige cuidadosamente redondeos de raíz cuadrada obtenidos con punto flotante.`)
    ],q('¿Por qué se recorren los valores v de mayor a menor al procesar p?', ['Para obtener primos ordenados','Para que G(v/p) siga siendo de la etapa anterior','Porque G es decreciente'],1,'La recurrencia elimina múltiplos usando los conteos anteriores a p; actualizar primero los valores menores los modificaría demasiado pronto.')),

  a('matroid','Matroides: cuándo un algoritmo voraz tiene garantía','Reconoce independencia e intercambio detrás de Kruskal, bases lineales y cupos por categoría.',
    ['usaco-gold-mst','usaco-adv-xor-basis'],['Verificar los tres axiomas de un matroide','Justificar selección voraz mediante intercambio'],[
      s('Un lenguaje común para independencia',`Un matroide tiene un conjunto finito E y una familia de subconjuntos independientes. Cumple tres axiomas: el vacío es independiente; cualquier subconjunto de un independiente también lo es; si A y B son independientes y |A|<|B|, existe un elemento de B fuera de A que puede añadirse a A conservando independencia. El tercero se llama intercambio y es la condición fuerte. Una familia hereditaria por sí sola no garantiza que elegir elementos baratos en orden produzca el mejor resultado.`),
      s('Ejemplos que ya conoces',`En un matroide gráfico, E son aristas y los independientes son bosques; añadir una arista es válido si no cierra un ciclo. En uno lineal, E son vectores y los independientes son conjuntos linealmente independientes. En uno de partición, E se divide en categorías y cada categoría tiene un cupo. Por ejemplo, elegir a lo sumo dos problemas de grafos y uno de geometría forma un matroide. El matroide uniforme permite cualquier conjunto de tamaño como máximo r.`),
      s('Por qué funciona ordenar por peso',`Una base es un independiente que no puede ampliarse; el axioma de intercambio obliga a que todas las bases tengan el mismo tamaño. Para hallar una base de peso mínimo, ordena elementos por peso creciente y añade cada uno si conserva independencia. Si una base óptima difiere de la elección voraz, un intercambio permite introducir el elemento elegido sin aumentar peso, manteniendo una base óptima compatible con el prefijo. Kruskal es exactamente este esquema en el matroide gráfico, donde DSU implementa la prueba de independencia.`),
      s('Costo, contraejemplos y práctica',`Si probar independencia cuesta T y hay n elementos, el esquema general requiere O(n log n+nT). El oráculo concreto puede tener una implementación incremental mucho más rápida. Para peso máximo de un conjunto independiente sin tamaño fijado, no agregues elementos de peso negativo solo para completar una base; la variante del objetivo importa. Practica demostrando el intercambio para cupos por categorías. Después prueba conjuntos de vértices sin aristas internas: aunque sean hereditarios, generalmente no forman un matroide. Busca un independiente pequeño maximal y otro mayor para exhibir la falla del axioma.`)
    ],q('¿Qué axioma falta si una familia contiene el vacío y es cerrada por subconjuntos?', ['Orden por peso','Intercambio entre independientes de tamaños distintos','Conectividad'],1,'La heredabilidad no basta; el intercambio permite ampliar el conjunto menor usando algún elemento del mayor.')),

  a('matroid-isect','Intersección de matroides','Encuentra el mayor conjunto que respeta dos tipos distintos de independencia.',
    ['usaco-adv-matroid','usaco-adv-max-flow'],['Construir un grafo de intercambio dirigido','Aumentar la solución con un camino más corto'],[
      s('Dos reglas pueden romper el voraz',`Deseamos elegir aristas que formen un bosque y respeten cupos por color. La primera regla es un matroide gráfico y la segunda uno de partición, ambos sobre el mismo conjunto E. Un conjunto puede ser independiente en cada uno por separado, pero elegir vorazmente bajo ambas restricciones no tiene la garantía de un solo matroide: su intersección no necesariamente es un matroide. El algoritmo de intersección busca un conjunto común de cardinalidad máxima mediante intercambios coordinados.`),
      s('Construir el grafo de intercambios',`Mantén S independiente en ambos matroides. Para x fuera de S e y dentro, añade y→x si S−y+x es independiente en M1, y x→y si lo es en M2. Los candidatos iniciales son x que pueden añadirse directamente en M1; los finales, x que pueden añadirse directamente en M2. Busca con BFS un camino más corto de un candidato inicial a uno final. Alternará elementos fuera y dentro de S. Invierte su pertenencia: agregas uno más de los que retiras.`),
      s('Ejemplo mediante emparejamientos',`El emparejamiento bipartito es una intersección de dos matroides de partición: a lo sumo una arista por vértice izquierdo y por vértice derecho. Con aristas a–1, a–2 y b–1, partir de S={a–1} impide añadir cualquiera directamente en ambos lados. El camino de intercambio b–1, a–1, a–2 retira a–1 y agrega las otras dos, obteniendo tamaño dos. El camino más corto conserva ambas independencias; cuando ya no existe, el teorema de intersección garantiza optimalidad de cardinalidad.`),
      s('Costo y transformaciones',`Si n=|E| y una consulta de independencia cuesta T, reconstruir todas las aristas del grafo y hacer hasta n aumentos da una cota sencilla O(n³T+n³), con O(n²) memoria para el grafo. Implementaciones que explotan rango y oráculos especiales mejoran esto. El matroide dual tiene como bases los complementos de bases originales. Contraer un independiente A modela exigirlo de antemano: B es independiente tras contraer si A unión B era independiente. Practica con emparejamientos pequeños y luego bosques con colores; una versión ponderada necesita otro algoritmo y no queda resuelta por BFS de cardinalidad.`)
    ],q('¿Qué ocurre al alternar pertenencia sobre un camino aumentante?', ['Se agregan exactamente dos elementos netos','Se agrega un elemento neto manteniendo ambas independencias','Se pierde una de las restricciones'],1,'El camino empieza y termina fuera de S y alterna dentro/fuera, por lo que incluye un elemento externo más que internos.')),

  a('random','Algoritmos aleatorizados y probabilidad de error','Diseña muestreos y estructuras aleatorias con una cota explícita, no solo con esperanza de suerte.',
    ['usaco-gold-hashing','usaco-gold-combo'],['Separar tiempo aleatorio de respuesta aleatoria','Acotar fallos de muestreo y verificar candidatos'],[
      s('Dos formas de usar azar',`Un algoritmo Las Vegas siempre da una respuesta correcta, pero su tiempo depende de decisiones aleatorias; un treap con prioridades aleatorias es un ejemplo de análisis esperado. Un algoritmo Monte Carlo tiene un costo acotado o controlado, pero puede equivocarse con cierta probabilidad. El objetivo al usarlo en concursos es demostrar una cota suficiente para todas las consultas y casos. Una semilla aleatoria no arregla una reducción incorrecta ni reemplaza la prueba de que una muestra puede descubrir la respuesta.`),
      s('Aprovechar muchos testigos',`Supón que al menos una fracción p de los elementos revela un candidato óptimo. Con k muestras uniformes e independientes con reemplazo, la probabilidad de no tocar ningún testigo es (1−p)^k. Si p≥1/2 y k=30, el fallo es como máximo 2^−30. Después de obtener un candidato, verifícalo exactamente contra los datos cuando sea posible: así puedes evitar aceptar candidatos inválidos, aunque todavía podrías no encontrar el mejor. Define claramente cuál de esos dos errores permite tu procedimiento.`),
      s('Un ejemplo de frecuencia',`Quieres encontrar un valor que aparezca al menos en un tercio de un arreglo. Cada muestra tiene probabilidad al menos 1/3 de tocarlo, así que veinte muestras lo omiten con probabilidad a lo sumo (2/3)^20, menor que 0.00031. Cuenta exactamente la frecuencia de cada valor distinto muestreado antes de reportarlo. Este problema concreto también tiene algoritmos deterministas eficientes; sirve como laboratorio para comprobar el razonamiento probabilístico, no como motivo para añadir azar donde no hace falta.`),
      s('Todo el experimento cuenta',`Si realizas Q consultas con probabilidad de fallo individual ε, la unión de eventos da una cota Qε aunque no sean independientes. Por eso una probabilidad pequeña para una sola consulta puede no bastar globalmente. Usa uniform_int_distribution para muestrear índices y guarda la semilla durante pruebas para reproducir fallos. El ejemplo con verificación directa cuesta O(kn) y O(k) memoria; tablas de frecuencia pueden cambiar ese balance. Practica estimando la tasa de fallos con un generador y contrástala con la fórmula, sin confundir evidencia experimental con garantía matemática.`)
    ],q('Si cada muestra independiente tiene probabilidad p de ser testigo, ¿cuál es la probabilidad de fallar k veces?', ['p·k','(1−p)^k','1−p^k'],1,'Fallar una vez tiene probabilidad 1−p y la independencia permite multiplicar ese factor k veces.')),

  a('interactive','Problemas interactivos y de comunicación','Diseña preguntas informativas y protocolos que no se bloqueen al conversar con el juez.',
    ['usaco-silver-binary-search','usaco-silver-intro-bitwise','usaco-general-input-output'],['Separar presupuesto de consultas y tiempo de cómputo','Demostrar un protocolo de información limitada'],[
      s('El programa participa en una conversación',`En un problema interactivo no recibes toda la entrada al inicio. Envías una consulta con formato exacto, vacías el búfer de salida y lees la respuesta del juez. En C++, endl vacía el búfer; si usas un salto de línea normal, añade flush cuando el protocolo lo necesita. Respeta límites de consultas, rangos y respuestas de error. No imprimas mensajes de depuración por la salida del protocolo: puedes usar stderr durante pruebas locales. La respuesta final suele tener un formato distinto de una pregunta.`),
      s('Cuánta información trae cada pregunta',`Si hay N candidatos equiprobables y cada pregunta solo responde sí o no, un árbol de decisión con q preguntas distingue como máximo 2^q casos. Esto sugiere una cota inferior ceil(log2 N), pero solo se alcanza si las preguntas permitidas pueden dividir bien las posibilidades. Para un número oculto de uno a ocho y preguntas «¿es como máximo x?», consulta cuatro, luego el punto medio del intervalo restante: tres preguntas bastan. Mantén el invariante de que la respuesta sigue dentro del intervalo.`),
      s('Comunicar con un cambio: un ejemplo XOR',`Imagina 2^k monedas etiquetadas de 0 a 2^k−1. Una persona ve un objetivo t y debe comunicarlo volteando exactamente una moneda; otra solo observa el tablero final. Ambas acuerdan calcular c como XOR de etiquetas de monedas cara arriba. La primera voltea la moneda j=c XOR t. Voltear j cambia el XOR total a c XOR j=t, así que la segunda recupera el objetivo. Incluso j=0 funciona: voltear la moneda cero deja el XOR igual cuando ya era t.`),
      s('Simular antes de enviar',`Construye un juez local que oculte datos, responda preguntas, cuente consultas y rechace formatos inválidos. Ensaya todos los objetivos de dominios pequeños y casos adversos en los extremos; mide consultas separadamente del tiempo de ejecución. La búsqueda binaria necesita O(log N) preguntas y memoria O(1), pero otros protocolos pueden requerir más cómputo para ahorrar comunicación. En problemas de dos programas, revisa qué información comparte cada uno y qué bits pueden transmitirse. No asumas que una variable global o un archivo local existe para ambos: solo el canal autorizado transmite información.`)
    ],q('En el protocolo de monedas, ¿qué etiqueta debe voltearse si c=6 y t=3?', ['3','5','9'],1,'6 XOR 3=5; el nuevo XOR será 6 XOR 5=3, que es el objetivo.')),

  a('vectorization','Vectorización en C++ y rendimiento medido','Comprende SIMD, dependencias de bucles y las condiciones reales para optimizar sin cambiar resultados.',
    ['usaco-bronze-time-comp','usaco-plat-bitsets','usaco-general-cpp-command'],['Reconocer iteraciones que pueden procesarse juntas','Medir optimizaciones y revisar compatibilidad del compilador'],[
      s('Una instrucción, varias posiciones',`SIMD permite realizar la misma operación sobre varios datos en registros anchos. Por ejemplo, sumar dos arreglos elemento a elemento tiene iteraciones independientes y es buen candidato para vectorización automática. En cambio, una suma de prefijos a[i]+=a[i−1] tiene una dependencia entre iteraciones que exige otro tratamiento. La vectorización cambia factores constantes, no convierte O(n²) en O(n log n). Primero elige un algoritmo apropiado y después estudia si sus accesos a memoria y operaciones permiten aprovechar la máquina.`),
      s('Ayudar al compilador',`Arreglos contiguos, bucles simples y ausencia de alias ambiguo facilitan que el compilador demuestre independencia. Los niveles de optimización y sus estrategias dependen de versión y plataforma; consulta los reportes de vectorización de GCC o Clang para saber qué transformaron. Las instrucciones disponibles también dependen de la CPU. Activar AVX2 explícitamente puede producir un ejecutable que no funciona en una máquina sin ese soporte, y las directivas específicas de GCC no son una interfaz portátil de C++17.`),
      s('Un bucle portable para experimentar',`El programa suma dos arreglos de enteros sin signo y luego imprime una suma de comprobación. Puedes aumentar el tamaño y medir versiones compiladas con optimización habitual y con reportes del compilador. El resultado debe conservarse; imprimir una comprobación evita que todo el trabajo se elimine como inútil. Para estos cuatro elementos, c=[6,8,10,12] y la suma es 36. No concluyas que hubo SIMD solo porque una versión corre más rápido: otras optimizaciones también influyen.`, String.raw`#include <iostream>
#include <vector>
#include <cstdint>
using namespace std;
int main(){
  vector<uint32_t> a={1,2,3,4},b={5,6,7,8},c(a.size());
  for(size_t i=0;i<a.size();++i) c[i]=a[i]+b[i];
  uint64_t checksum=0;
  for(uint32_t value:c) checksum+=value;
  cout<<checksum<<'\n';
}`),
      s('Medición y semántica',`El tiempo sigue siendo O(n) y la memoria O(n); el límite puede estar en ancho de banda de memoria en vez de cómputo. Repite mediciones con tamaños representativos y separa lectura, cómputo y escritura. Opciones de matemáticas rápidas pueden permitir reordenar operaciones de punto flotante y cambiar resultados, tratamiento de NaN o ceros con signo; no son una aceleración gratuita. El desbordamiento de enteros con signo sigue siendo comportamiento indefinido y no debe usarse como truco. Practica comparando resultados exactos o tolerancias justificadas, y conserva una versión portable como referencia.`)
    ],q('¿Qué bucle es candidato directo a vectorización por independencia?', ['c[i]=a[i]+b[i]','a[i]+=a[i−1]','Procesar el siguiente nodo según el anterior'],0,'Cada c[i] depende de posiciones independientes de entrada; no necesita el resultado calculado en la iteración anterior.')),
];
